var e=[{id:`i-hk-01`,phase:`hooks-in-depth`,question:{en:`Why must hooks be called in the same order on every render?`,ar:`لماذا يجب استدعاء الخطّافات بالترتيب نفسه في كل عرض؟`},options:[{text:{en:`React matches each hook to its stored state by call order, not by name.`,ar:`لأن رياكت تطابق كل خطّاف بحالته المخزّنة حسب ترتيب الاستدعاء لا الاسم.`},correct:!0},{text:{en:`Because the linter cannot parse conditional hooks.`,ar:`لأن أداة الفحص لا تستطيع تحليل الخطّافات الشرطية.`}},{text:{en:`Because hooks are compiled into a switch statement.`,ar:`لأن الخطّافات تُصرَّف إلى جملة switch.`}},{text:{en:`To keep the component tree alphabetically ordered.`,ar:`للحفاظ على ترتيب شجرة المكوّنات أبجديًا.`}}],explain:{en:`State lives in a list indexed by position. Skip a hook on one render and every hook after it reads the previous hook's slot — silently, with no error.`,ar:`تعيش الحالة في قائمة مفهرسة حسب الموضع. فتخطّي خطّاف في عرض واحد يجعل كل خطّاف بعده يقرأ خانة الخطّاف السابق — بصمت ودون خطأ.`}},{id:`i-hk-02`,phase:`hooks-in-depth`,question:{en:"What does returning a function from `useEffect` do?",ar:"ماذا تفعل إعادة دالة من `useEffect`؟"},options:[{text:{en:`Registers cleanup, run before the next effect and on unmount.`,ar:`تسجّل تنظيفًا يعمل قبل التأثير التالي وعند الإزالة.`},correct:!0},{text:{en:`Schedules the effect to run again.`,ar:`تجدول تشغيل التأثير مرة أخرى.`}},{text:{en:`Returns a value to the component.`,ar:`تُعيد قيمة إلى المكوّن.`}},{text:{en:`Nothing — the return value is ignored.`,ar:`لا شيء — فالقيمة المُعادة تُتجاهَل.`}}],explain:{en:`Cleanup runs before *every* re-run, not only on unmount. That is what stops subscriptions, timers and stale fetches from piling up.`,ar:`يعمل التنظيف قبل *كل* إعادة تشغيل لا عند الإزالة فقط. وهذا ما يمنع تراكم الاشتراكات والمؤقّتات والطلبات القديمة.`}},{id:`i-hk-03`,phase:`hooks-in-depth`,question:{en:"An effect with `[]` as its dependency array runs when?",ar:"متى يعمل تأثير مصفوفة اعتمادياته `[]`؟"},options:[{text:{en:`Once after the first render.`,ar:`مرة واحدة بعد العرض الأول.`},correct:!0},{text:{en:`After every render.`,ar:`بعد كل عرض.`}},{text:{en:`Never.`,ar:`أبدًا.`}},{text:{en:`Only when the component unmounts.`,ar:`فقط عند إزالة المكوّن.`}}],explain:{en:`An empty array means "nothing this effect reads can change". In development with Strict Mode it runs twice on purpose, to surface missing cleanup.`,ar:`المصفوفة الفارغة تعني «لا شيء يقرؤه هذا التأثير قابل للتغيّر». وفي التطوير مع الوضع الصارم يعمل مرتين عن قصد لكشف التنظيف الناقص.`}},{id:`i-hk-04`,phase:`hooks-in-depth`,question:{en:`Which of these does NOT need an Effect?`,ar:`أيٌّ من هذه لا يحتاج إلى Effect؟`},options:[{text:{en:`Filtering a list whenever a search box changes.`,ar:`تصفية قائمة كلما تغيّر مربّع البحث.`},correct:!0},{text:{en:`Subscribing to a WebSocket.`,ar:`الاشتراك في WebSocket.`}},{text:{en:"Setting up a `setInterval` timer.",ar:"إعداد مؤقّت `setInterval`."}},{text:{en:"Syncing state to `document.title`.",ar:"مزامنة الحالة مع `document.title`."}}],explain:{en:`Filtering is derivation — compute it during render. The other three genuinely reach outside React, which is exactly what effects are for.`,ar:`التصفية اشتقاق — احسبها أثناء العرض. أما الثلاثة الأخرى فتصل فعلًا إلى خارج رياكت، وهذا بالضبط ما وُجدت التأثيرات من أجله.`}},{id:`i-hk-05`,phase:`hooks-in-depth`,question:{en:"What is the main difference between `useRef` and `useState`?",ar:"ما الفرق الرئيسي بين `useRef` و `useState`؟"},options:[{text:{en:`Changing a ref does not trigger a re-render.`,ar:`أن تغيير المرجع لا يُحفّز إعادة العرض.`},correct:!0},{text:{en:`Refs cannot hold objects.`,ar:`أن المراجع لا تستطيع حمل كائنات.`}},{text:{en:`Refs are reset on every render.`,ar:`أن المراجع تُعاد ضبطها في كل عرض.`}},{text:{en:`Refs only work with DOM nodes.`,ar:`أن المراجع تعمل مع عقد DOM فقط.`}}],explain:{en:`A ref is a mutable box that survives renders without causing them. That makes it right for timer ids and DOM nodes, and wrong for anything the UI displays.`,ar:`المرجع صندوق قابل للتعديل يبقى عبر عمليات العرض دون أن يسبّبها. وهذا يجعله مناسبًا لمعرّفات المؤقّتات وعقد DOM، وغير مناسب لأي شيء تعرضه الواجهة.`}},{id:`i-hk-06`,phase:`hooks-in-depth`,question:{en:"A component reads `useContext(ThemeContext)`. When does it re-render?",ar:"مكوّن يقرأ `useContext(ThemeContext)`. متى يُعاد عرضه؟"},options:[{text:{en:"Whenever the provider's `value` changes identity.",ar:"كلما تغيّرت هوية `value` في المزوّد."},correct:!0},{text:{en:`Only when its own props change.`,ar:`فقط حين تتغيّر خصائصه.`}},{text:{en:`Only when the whole app re-renders.`,ar:`فقط حين يُعاد عرض التطبيق كله.`}},{text:{en:`Never — context reads are free.`,ar:`أبدًا — فقراءة السياق مجانية.`}}],explain:{en:"Every consumer re-renders when the value changes. Passing a fresh object literal as `value` on each render therefore re-renders all consumers every time.",ar:"يُعاد عرض كل مستهلك عند تغيّر القيمة. لذا فتمرير كائن حرفي جديد كـ `value` في كل عرض يُعيد عرض كل المستهلكين في كل مرة."}},{id:`i-hk-07`,phase:`hooks-in-depth`,question:{en:"When is `useReducer` a better fit than `useState`?",ar:"متى تكون `useReducer` أنسب من `useState`؟"},options:[{text:{en:`When several values change together as one transition.`,ar:`حين تتغيّر عدة قيم معًا كانتقال واحد.`},correct:!0},{text:{en:`Whenever the state is an object.`,ar:`كلما كانت الحالة كائنًا.`}},{text:{en:`When the state must persist across reloads.`,ar:`حين يجب أن تبقى الحالة بعد إعادة التحميل.`}},{text:{en:`When performance is critical.`,ar:`حين يكون الأداء حرجًا.`}}],explain:{en:"A reducer names the transitions — `submit_started`, `submit_failed` — instead of scattering four setters across a handler. Neither is faster than the other.",ar:"يُسمّي المُختزِل الانتقالات — `submit_started` و `submit_failed` — بدل تشتيت أربع دوال ضبط في معالج واحد. ولا أحدهما أسرع من الآخر."}},{id:`i-hk-08`,phase:`hooks-in-depth`,question:{en:`What makes a function a custom hook rather than a plain helper?`,ar:`ما الذي يجعل الدالة خطّافًا مخصّصًا بدل دالة مساعدة عادية؟`},options:[{text:{en:"It calls other hooks, and its name begins with `use`.",ar:"أنها تستدعي خطّافات أخرى، ويبدأ اسمها بـ `use`."},correct:!0},{text:{en:"It is defined in a `hooks/` folder.",ar:"أنها معرّفة في مجلد `hooks/`."}},{text:{en:`It returns an array.`,ar:`أنها تُعيد مصفوفة.`}},{text:{en:`It is exported as the default.`,ar:`أنها مُصدَّرة كافتراضي.`}}],explain:{en:"The `use` prefix is how the linter knows to enforce the rules of hooks inside it. A helper that calls no hooks is just a function — keep it one.",ar:"البادئة `use` هي ما يجعل أداة الفحص تفرض قواعد الخطّافات بداخلها. أما الدالة المساعدة التي لا تستدعي خطّافات فهي دالة عادية — أبقِها كذلك."}},{id:`i-hk-09`,phase:`hooks-in-depth`,question:{en:"Two components both call `useCounter()`. Do they share state?",ar:"مكوّنان يستدعيان `useCounter()`. هل يتشاركان الحالة؟"},options:[{text:{en:`No — each call gets its own independent state.`,ar:`لا — كل استدعاء يحصل على حالته المستقلّة.`},correct:!0},{text:{en:`Yes, custom hooks are singletons.`,ar:`نعم، فالخطّافات المخصّصة وحيدة النسخة.`}},{text:{en:`Only if they are siblings.`,ar:`فقط إذا كانا شقيقين.`}},{text:{en:`Only when wrapped in a provider.`,ar:`فقط عند تغليفهما بمزوّد.`}}],explain:{en:`Custom hooks reuse *logic*, never state. To share the value itself you need context or a store.`,ar:`تُعيد الخطّافات المخصّصة استخدام *المنطق* لا الحالة أبدًا. ولمشاركة القيمة نفسها تحتاج سياقًا أو مخزنًا.`}},{id:`i-hk-10`,phase:`hooks-in-depth`,question:{en:`What problem does an empty dependency array cause when the effect reads a prop?`,ar:`ما المشكلة التي تسبّبها مصفوفة اعتماديات فارغة حين يقرأ التأثير خاصية؟`},options:[{text:{en:`The effect keeps seeing the value from the first render.`,ar:`يستمر التأثير في رؤية قيمة العرض الأول.`},correct:!0},{text:{en:`React throws an error at runtime.`,ar:`تُطلق رياكت خطأً وقت التشغيل.`}},{text:{en:`The effect runs on every render instead.`,ar:`يعمل التأثير في كل عرض بدلًا من ذلك.`}},{text:{en:`The component never mounts.`,ar:`لا يُركَّب المكوّن أبدًا.`}}],explain:{en:`A stale closure: the effect captured that render's variables and never re-ran, so it keeps using values that have long since changed.`,ar:`إغلاق قديم: التقط التأثير متغيّرات ذلك العرض ولم يُعَد تشغيله، فيظلّ يستخدم قيمًا تغيّرت منذ زمن.`}},{id:`i-hk-11`,phase:`hooks-in-depth`,question:{en:"What does `useMemo` actually cache?",ar:"ماذا تخزّن `useMemo` فعليًا؟"},options:[{text:{en:`The result of a calculation between renders.`,ar:`نتيجة عملية حسابية بين عمليات العرض.`},correct:!0},{text:{en:`The component's rendered output.`,ar:`ناتج عرض المكوّن.`}},{text:{en:`A network response.`,ar:`استجابة شبكية.`}},{text:{en:`The function itself.`,ar:`الدالة نفسها.`}}],explain:{en:"`useMemo` caches a value; `useCallback` caches a function. React 19's compiler applies most of this automatically, so reach for it after measuring, not before.",ar:"تخزّن `useMemo` قيمة، وتخزّن `useCallback` دالة. ويُطبّق مُصرِّف رياكت 19 معظم ذلك تلقائيًا، فاستخدمها بعد القياس لا قبله."}},{id:`i-hk-12`,phase:`hooks-in-depth`,question:{en:`Where may a hook be called?`,ar:`أين يُسمح باستدعاء الخطّاف؟`},options:[{text:{en:`At the top level of a component or another hook.`,ar:`في المستوى الأعلى لمكوّن أو لخطّاف آخر.`},correct:!0},{text:{en:`Anywhere inside a component, including handlers.`,ar:`في أي مكان داخل المكوّن بما في ذلك المعالجات.`}},{text:{en:`In any function in the codebase.`,ar:`في أي دالة في المشروع.`}},{text:{en:`Only in the root component.`,ar:`في المكوّن الجذر فقط.`}}],explain:{en:`Two places only. Calling one inside an event handler, a loop or a plain utility breaks the call-order guarantee React depends on.`,ar:`مكانان فقط. واستدعاؤه داخل معالج حدث أو حلقة أو دالة مساعدة عادية يكسر ضمان ترتيب الاستدعاء الذي تعتمد عليه رياكت.`}},{id:`i-hk-13`,phase:`hooks-in-depth`,question:{en:`An effect fetches data. How do you stop a slow earlier response overwriting a newer one?`,ar:`تأثير يجلب بيانات. كيف تمنع استجابة قديمة بطيئة من استبدال استجابة أحدث؟`},options:[{text:{en:"Track it with a cleanup flag or an `AbortController`.",ar:"تتبّعها بعَلَم تنظيف أو بـ `AbortController`."},correct:!0},{text:{en:"Add a `setTimeout` before setting state.",ar:"أضف `setTimeout` قبل ضبط الحالة."}},{text:{en:"Use `await` twice.",ar:"استخدم `await` مرتين."}},{text:{en:`Nothing — React handles ordering.`,ar:`لا شيء — فرياكت تتكفّل بالترتيب.`}}],explain:{en:`The classic race condition. Cleanup flips a flag so the stale response is discarded rather than written into state after the newer one.`,ar:`هذا هو تعارض الطلبات الكلاسيكي. يقلب التنظيف عَلَمًا فتُهمَل الاستجابة القديمة بدل كتابتها في الحالة بعد الأحدث.`}},{id:`i-hk-14`,phase:`hooks-in-depth`,question:{en:"What is wrong with `const ref = useRef(0)` used to show a live count on screen?",ar:"ما الخطأ في استخدام `const ref = useRef(0)` لعرض عدّاد حيّ على الشاشة؟"},options:[{text:{en:"Changing `ref.current` re-renders nothing, so the display never updates.",ar:"أن تغيير `ref.current` لا يُعيد عرض شيء، فلا يتحدّث المعروض أبدًا."},correct:!0},{text:{en:`Refs cannot store numbers.`,ar:`أن المراجع لا تستطيع تخزين الأرقام.`}},{text:{en:`The ref resets to 0 on each render.`,ar:`أن المرجع يعود إلى 0 في كل عرض.`}},{text:{en:`React warns and refuses to render.`,ar:`أن رياكت تُحذّر وترفض العرض.`}}],explain:{en:`The value updates correctly; the screen just never hears about it. Anything the user sees belongs in state.`,ar:`تتحدّث القيمة بشكل صحيح، لكن الشاشة لا تعلم بذلك أبدًا. فكل ما يراه المستخدم ينتمي إلى الحالة.`}},{id:`i-hk-15`,phase:`hooks-in-depth`,question:{en:"Why does `useEffect` warn about a missing dependency?",ar:"لماذا تُحذّر `useEffect` من اعتمادية ناقصة؟"},options:[{text:{en:`The effect reads a value that can change, so it may act on stale data.`,ar:`لأن التأثير يقرأ قيمة قابلة للتغيّر، فقد يعمل على بيانات قديمة.`},correct:!0},{text:{en:`Missing dependencies always cause infinite loops.`,ar:`لأن الاعتماديات الناقصة تسبّب حلقات لا نهائية دائمًا.`}},{text:{en:`React needs the array to be a fixed length.`,ar:`لأن رياكت تحتاج المصفوفة بطول ثابت.`}},{text:{en:`It is purely a style rule.`,ar:`لأنها قاعدة تنسيقية بحتة.`}}],explain:{en:`Silencing the warning is almost never the fix. Either add the dependency, move the value inside the effect, or question whether you need the effect at all.`,ar:`كتم التحذير ليس الحلّ تقريبًا أبدًا. إما أن تضيف الاعتمادية أو تنقل القيمة داخل التأثير أو تتساءل إن كنت تحتاج التأثير أصلًا.`}},{id:`i-hk-16`,phase:`hooks-in-depth`,question:{en:`How do you avoid re-rendering every context consumer on each parent render?`,ar:`كيف تتجنّب إعادة عرض كل مستهلكي السياق في كل عرض للأب؟`},options:[{text:{en:"Give the provider a stable `value` instead of a fresh object each render.",ar:"امنح المزوّد `value` ثابتة بدل كائن جديد في كل عرض."},correct:!0},{text:{en:"Wrap every consumer in `useEffect`.",ar:"غلّف كل مستهلك بـ `useEffect`."}},{text:{en:`Use more providers.`,ar:`استخدم مزوّدات أكثر.`}},{text:{en:`Move the provider lower in the tree.`,ar:`انقل المزوّد إلى أسفل الشجرة.`}}],explain:{en:"`value={{ user, setUser }}` builds a new object every render, so identity always changes. Memoise it, or split rarely-changing and often-changing values into separate contexts.",ar:"تبني `value={{ user, setUser }}` كائنًا جديدًا في كل عرض فتتغيّر الهوية دائمًا. خزّنها أو افصل القيم نادرة التغيّر عن كثيرة التغيّر في سياقات منفصلة."}},{id:`i-hk-17`,phase:`hooks-in-depth`,question:{en:`What does a reducer function receive and return?`,ar:`ماذا تستقبل دالة المُختزِل وماذا تُعيد؟`},options:[{text:{en:`The current state and an action; it returns the next state.`,ar:`الحالة الحالية وإجراءً، وتُعيد الحالة التالية.`},correct:!0},{text:{en:`An action only; it mutates state in place.`,ar:`إجراءً فقط، وتُعدّل الحالة في مكانها.`}},{text:{en:`The previous and next state.`,ar:`الحالة السابقة والتالية.`}},{text:{en:`A dispatch function.`,ar:`دالة إرسال.`}}],explain:{en:`It must be pure: same state and action in, same state out, with no fetches or mutation. That purity is what makes reducers easy to test in isolation.`,ar:`يجب أن تكون نقية: الحالة والإجراء نفسهما يُنتجان الحالة نفسها، دون جلب أو تعديل. وهذه النقاء هو ما يجعل المُختزِلات سهلة الاختبار منفردة.`}},{id:`i-hk-18`,phase:`hooks-in-depth`,question:{en:`You want to focus an input after mount. Which tool fits?`,ar:`تريد تركيز حقل إدخال بعد التركيب. أي أداة تناسب؟`},options:[{text:{en:`A ref on the input, focused inside an effect.`,ar:`مرجع على الحقل يُركَّز داخل تأثير.`},correct:!0},{text:{en:"`useState` holding the DOM node.",ar:"`useState` تحمل عقدة DOM."}},{text:{en:"`document.querySelector` during render.",ar:"`document.querySelector` أثناء العرض."}},{text:{en:"`useMemo` returning the element.",ar:"`useMemo` تُعيد العنصر."}}],explain:{en:`The DOM node only exists after commit, so the effect is the right moment. Storing it in state would trigger a pointless extra render.`,ar:`لا توجد عقدة DOM إلا بعد التثبيت، فالتأثير هو اللحظة الصحيحة. أما تخزينها في الحالة فيُحفّز عرضًا إضافيًا بلا فائدة.`}},{id:`i-hk-19`,phase:`hooks-in-depth`,question:{en:`An effect sets state that is also in its dependency array. What happens?`,ar:`تأثير يضبط حالة موجودة أيضًا في مصفوفة اعتمادياته. ماذا يحدث؟`},options:[{text:{en:`An infinite loop: set → re-render → effect → set.`,ar:`حلقة لا نهائية: ضبط ← إعادة عرض ← تأثير ← ضبط.`},correct:!0},{text:{en:`React deduplicates it automatically.`,ar:`تحذف رياكت التكرار تلقائيًا.`}},{text:{en:`The effect runs exactly twice.`,ar:`يعمل التأثير مرتين بالضبط.`}},{text:{en:`Nothing — dependencies are ignored for setters.`,ar:`لا شيء — فالاعتماديات تُتجاهَل مع دوال الضبط.`}}],explain:{en:`React bails out only if the new value is identical. Setting a fresh object or array every time keeps the loop alive — often the sign the value should be derived instead.`,ar:`تنسحب رياكت فقط إذا كانت القيمة الجديدة مطابقة. أما ضبط كائن أو مصفوفة جديدة في كل مرة فيُبقي الحلقة حيّة — وغالبًا يدلّ ذلك على أن القيمة يجب اشتقاقها.`}},{id:`i-hk-20`,phase:`hooks-in-depth`,question:{en:`What does a custom hook typically return?`,ar:`ماذا يُعيد الخطّاف المخصّص عادةً؟`},options:[{text:{en:`Whatever its caller needs — a value, a tuple or an object.`,ar:`ما يحتاجه مستدعيه — قيمة أو زوجًا أو كائنًا.`},correct:!0},{text:{en:"Always a two-item array, like `useState`.",ar:"مصفوفة من عنصرين دائمًا مثل `useState`."}},{text:{en:`Always JSX.`,ar:`JSX دائمًا.`}},{text:{en:`Nothing — hooks return void.`,ar:`لا شيء — فالخطّافات تُعيد void.`}}],explain:{en:`A tuple suits two values you will rename; an object suits three or more, since named keys beat remembering positions.`,ar:`يناسب الزوج قيمتين ستعيد تسميتهما، ويناسب الكائن ثلاثًا فأكثر لأن المفاتيح المسمّاة أفضل من تذكّر المواضع.`}},{id:`i-hk-21`,phase:`hooks-in-depth`,question:{en:`Why does Strict Mode run effects twice in development?`,ar:`لماذا يُشغّل الوضع الصارم التأثيرات مرتين في التطوير؟`},options:[{text:{en:`To reveal effects that are missing cleanup.`,ar:`لكشف التأثيرات التي ينقصها التنظيف.`},correct:!0},{text:{en:`To measure render performance.`,ar:`لقياس أداء العرض.`}},{text:{en:`It is a bug in React 19.`,ar:`إنه خلل في رياكت 19.`}},{text:{en:`To warm the network cache.`,ar:`لتسخين ذاكرة الشبكة المؤقتة.`}}],explain:{en:`Mount, unmount, mount again. An effect that tidies up correctly is unaffected; one that leaks a subscription or a timer shows it immediately.`,ar:`تركيب ثم إزالة ثم تركيب مجدّدًا. فالتأثير الذي ينظّف بشكل صحيح لا يتأثّر، أما الذي يُسرّب اشتراكًا أو مؤقّتًا فيظهر فورًا.`}},{id:`i-hk-22`,phase:`hooks-in-depth`,question:{en:"Which is the better place for `const filtered = items.filter(...)`?",ar:"أين الموضع الأفضل لـ `const filtered = items.filter(...)`؟"},options:[{text:{en:`Directly in the component body during render.`,ar:`مباشرةً في جسم المكوّن أثناء العرض.`},correct:!0},{text:{en:`In an effect that writes it to state.`,ar:`في تأثير يكتبها إلى الحالة.`}},{text:{en:`In a ref updated on change.`,ar:`في مرجع يُحدَّث عند التغيير.`}},{text:{en:`In a reducer action.`,ar:`في إجراء مُختزِل.`}}],explain:{en:`Deriving during render is always correct and always in sync. The effect version renders once with stale data before catching up, and adds a second source of truth.`,ar:`الاشتقاق أثناء العرض صحيح دائمًا ومتزامن دائمًا. أما صيغة التأثير فتعرض مرة ببيانات قديمة قبل أن تلحق، وتضيف مصدرًا ثانيًا للحقيقة.`}},{id:`i-hw-01`,phase:`how-react-works`,question:{en:`What are the three beats of a React update, in order?`,ar:`ما النبضات الثلاث لتحديث رياكت بالترتيب؟`},options:[{text:{en:`Trigger, render, commit.`,ar:`تحفيز ثم عرض ثم تثبيت.`},correct:!0},{text:{en:`Render, diff, paint.`,ar:`عرض ثم مقارنة ثم رسم.`}},{text:{en:`Mount, update, unmount.`,ar:`تركيب ثم تحديث ثم إزالة.`}},{text:{en:`Commit, render, trigger.`,ar:`تثبيت ثم عرض ثم تحفيز.`}}],explain:{en:`Something triggers an update, React calls your components to get a description, then commits the minimum DOM changes. The browser paints afterwards.`,ar:`شيء ما يُحفّز تحديثًا، فتستدعي رياكت مكوّناتك للحصول على وصف، ثم تُثبّت أقل تغييرات ممكنة في DOM. ويرسم المتصفح بعد ذلك.`}},{id:`i-hw-02`,phase:`how-react-works`,question:{en:`What does "rendering" mean in React?`,ar:`ماذا يعني «العرض» في رياكت؟`},options:[{text:{en:`Calling your component function to get a description of the UI.`,ar:`استدعاء دالة مكوّنك للحصول على وصف للواجهة.`},correct:!0},{text:{en:`Painting pixels on the screen.`,ar:`رسم البكسلات على الشاشة.`}},{text:{en:`Writing to the DOM.`,ar:`الكتابة إلى DOM.`}},{text:{en:`Downloading the component chunk.`,ar:`تنزيل حزمة المكوّن.`}}],explain:{en:`This is why "re-rendered" does not mean "was slow" — a render is a function call. The DOM work happens at commit, and only where the description differs.`,ar:`ولهذا فـ «أُعيد عرضه» لا تعني «كان بطيئًا» — فالعرض استدعاء دالة. أما عمل DOM فيحدث عند التثبيت وفي مواضع اختلاف الوصف فقط.`}},{id:`i-hw-03`,phase:`how-react-works`,question:{en:`A parent re-renders. What happens to a child whose props did not change?`,ar:`أُعيد عرض الأب. ماذا يحدث لابنٍ لم تتغيّر خصائصه؟`},options:[{text:{en:`It re-renders too, unless it is memoised.`,ar:`يُعاد عرضه أيضًا إلا إذا كان مخزّنًا.`},correct:!0},{text:{en:`It is skipped automatically.`,ar:`يُتخطّى تلقائيًا.`}},{text:{en:`It unmounts and remounts.`,ar:`يُزال ثم يُركَّب من جديد.`}},{text:{en:`React throws a warning.`,ar:`تُطلق رياكت تحذيرًا.`}}],explain:{en:`Re-rendering children is the default and is usually cheap, because the commit stage still changes nothing. Measure before memoising.`,ar:`إعادة عرض الأبناء هي الافتراض وهي رخيصة عادةً لأن مرحلة التثبيت لا تُغيّر شيئًا. قِس قبل التخزين.`}},{id:`i-hw-04`,phase:`how-react-works`,question:{en:`What does React compare during reconciliation?`,ar:`ماذا تقارن رياكت أثناء المطابقة؟`},options:[{text:{en:`The new element tree against the previous one.`,ar:`شجرة العناصر الجديدة بالسابقة.`},correct:!0},{text:{en:`The DOM against the database.`,ar:`DOM بقاعدة البيانات.`}},{text:{en:`The rendered HTML strings.`,ar:`نصوص HTML المعروضة.`}},{text:{en:`Component source code.`,ar:`الكود المصدري للمكوّنات.`}}],explain:{en:`Two lightweight JavaScript trees are diffed, and only the differences reach the DOM. Reading the real DOM would be far slower.`,ar:`تُقارَن شجرتا جافاسكربت خفيفتان ولا تصل إلى DOM إلا الفروق. فقراءة DOM الحقيقي ستكون أبطأ بكثير.`}},{id:`i-hw-05`,phase:`how-react-works`,question:{en:"React sees `<Profile />` replaced by `<Settings />` at the same position. What does it do?",ar:"ترى رياكت `<Profile />` مستبدلًا بـ `<Settings />` في الموضع نفسه. ماذا تفعل؟"},options:[{text:{en:`Destroys the old subtree and its state, then builds the new one.`,ar:`تهدم الشجرة القديمة وحالتها ثم تبني الجديدة.`},correct:!0},{text:{en:`Reuses the state, since the position is the same.`,ar:`تُعيد استخدام الحالة لأن الموضع نفسه.`}},{text:{en:`Merges the two components.`,ar:`تدمج المكوّنين.`}},{text:{en:`Warns and keeps the old one.`,ar:`تُحذّر وتُبقي القديم.`}}],explain:{en:`A different component type at the same position means a completely fresh subtree. Same type at the same position is what preserves state.`,ar:`نوع مكوّن مختلف في الموضع نفسه يعني شجرة فرعية جديدة تمامًا. أما النوع نفسه في الموضع نفسه فهو ما يحفظ الحالة.`}},{id:`i-hw-06`,phase:`how-react-works`,question:{en:`How do you deliberately reset a component's internal state?`,ar:`كيف تُعيد ضبط الحالة الداخلية لمكوّن عن قصد؟`},options:[{text:{en:"Give it a different `key`.",ar:"امنحه `key` مختلفًا."},correct:!0},{text:{en:"Pass a `reset` prop.",ar:"مرّر خاصية `reset`."}},{text:{en:"Call `component.reset()`.",ar:"استدعِ `component.reset()`."}},{text:{en:`Re-import the component.`,ar:`أعِد استيراد المكوّن.`}}],explain:{en:"A new key is a new identity, so React throws the old instance away. `<Form key={userId} />` clears the form when the user changes, with no effect needed.",ar:"المفتاح الجديد هوية جديدة، فترمي رياكت النسخة القديمة. و `<Form key={userId} />` يمسح النموذج عند تغيّر المستخدم دون حاجة إلى أي تأثير."}},{id:`i-hw-07`,phase:`how-react-works`,question:{en:`Which fix for an unnecessary re-render should you try first?`,ar:`أي حلٍّ لإعادة عرض غير ضرورية تجرّبه أولًا؟`},options:[{text:{en:`Restructure with composition so the expensive part is not a child of the changing state.`,ar:`أعِد الهيكلة بالتركيب ليخرج الجزء المكلف من كونه ابنًا للحالة المتغيّرة.`},correct:!0},{text:{en:"Wrap everything in `memo`.",ar:"غلّف كل شيء بـ `memo`."}},{text:{en:"Add `useCallback` to every handler.",ar:"أضف `useCallback` لكل معالج."}},{text:{en:`Move all state to a global store.`,ar:`انقل كل الحالة إلى مخزن عام.`}}],explain:{en:"Passing the expensive tree in as `children` means it is created by the parent and simply handed through, so a state change in the middle component cannot re-render it.",ar:"تمرير الشجرة المكلفة كـ `children` يعني أن الأب هو من ينشئها ويمرّرها فحسب، فلا يستطيع تغيّر الحالة في المكوّن الوسيط إعادة عرضها."}},{id:`i-hw-08`,phase:`how-react-works`,question:{en:`What does "state colocation" mean?`,ar:`ماذا يعني «توطين الحالة»؟`},options:[{text:{en:`Keeping state as close as possible to where it is used.`,ar:`إبقاء الحالة أقرب ما يمكن لمكان استخدامها.`},correct:!0},{text:{en:`Storing all state in one file.`,ar:`تخزين كل الحالة في ملف واحد.`}},{text:{en:`Sharing state between routes.`,ar:`مشاركة الحالة بين المسارات.`}},{text:{en:`Persisting state to storage.`,ar:`حفظ الحالة في التخزين.`}}],explain:{en:`State at the top re-renders everything below it. Push it down to the smallest component that needs it and the blast radius shrinks with no memoisation at all.`,ar:`الحالة في الأعلى تُعيد عرض كل ما تحتها. ادفعها لأصغر مكوّن يحتاجها فينكمش نطاق التأثير دون أي تخزين إطلاقًا.`}},{id:`i-hw-09`,phase:`how-react-works`,question:{en:`When does the browser actually paint?`,ar:`متى يرسم المتصفح فعليًا؟`},options:[{text:{en:`After React commits the changes to the DOM.`,ar:`بعد أن تُثبّت رياكت التغييرات في DOM.`},correct:!0},{text:{en:`During the render phase.`,ar:`أثناء مرحلة العرض.`}},{text:{en:`Before the component function runs.`,ar:`قبل تشغيل دالة المكوّن.`}},{text:{en:`Once per second on a timer.`,ar:`مرة كل ثانية عبر مؤقّت.`}}],explain:{en:"Render is pure calculation with nothing on screen yet. This ordering is why `useLayoutEffect` — which runs before paint — can measure and adjust without a visible flicker.",ar:"العرض حساب نقي ولا شيء على الشاشة بعد. وهذا الترتيب هو سبب قدرة `useLayoutEffect` — التي تعمل قبل الرسم — على القياس والتعديل دون وميض مرئي."}},{id:`i-hw-10`,phase:`how-react-works`,question:{en:`Why must a render be pure?`,ar:`لماذا يجب أن يكون العرض نقيًا؟`},options:[{text:{en:`React may call it repeatedly or discard the result.`,ar:`لأن رياكت قد تستدعيه مرارًا أو تُهمل النتيجة.`},correct:!0},{text:{en:`Because JavaScript forbids side effects in functions.`,ar:`لأن جافاسكربت تمنع الآثار الجانبية في الدوال.`}},{text:{en:`To make TypeScript inference work.`,ar:`لكي يعمل استنتاج تايب سكربت.`}},{text:{en:`Purity only matters on the server.`,ar:`لأن النقاء يهمّ على الخادم فقط.`}}],explain:{en:`With concurrent rendering a render can be started, paused and thrown away. A fetch or a mutation inside it would fire unpredictably.`,ar:`مع العرض المتزامن قد يبدأ العرض ويتوقّف ويُهمل. فأي جلب أو تعديل بداخله سينطلق بشكل غير متوقّع.`}},{id:`i-hw-11`,phase:`how-react-works`,question:{en:`Two list items swap places and both keep the correct text but the wrong input values. Why?`,ar:`تبادل عنصران في قائمة موضعيهما فاحتفظ كلاهما بالنص الصحيح وبقيم حقول خاطئة. لماذا؟`},options:[{text:{en:`Keys tie identity to position, so DOM state followed the slot.`,ar:`لأن المفاتيح تربط الهوية بالموضع، فتبعت حالة DOM الخانة.`},correct:!0},{text:{en:`The inputs are uncontrolled.`,ar:`لأن الحقول غير مُتحكَّم بها.`}},{text:{en:`React batched the updates.`,ar:`لأن رياكت جمّعت التحديثات.`}},{text:{en:`The list was not memoised.`,ar:`لأن القائمة غير مخزّنة.`}}],explain:{en:`Text comes from props and is rewritten, but DOM-held state such as an input's value or focus stays with the reused node. A stable key ties identity to the data instead.`,ar:`يأتي النص من الخصائص فيُعاد كتابته، أما الحالة المحفوظة في DOM كقيمة الحقل أو التركيز فتبقى مع العقدة المُعاد استخدامها. والمفتاح الثابت يربط الهوية بالبيانات بدلًا من ذلك.`}},{id:`i-hw-12`,phase:`how-react-works`,question:{en:"What does `memo` actually do to a component?",ar:"ماذا تفعل `memo` بالمكوّن فعليًا؟"},options:[{text:{en:`Skips its re-render when its props are shallowly equal.`,ar:`تتخطّى إعادة عرضه حين تتساوى خصائصه سطحيًا.`},correct:!0},{text:{en:`Caches its DOM nodes permanently.`,ar:`تخزّن عقد DOM الخاصة به دائمًا.`}},{text:{en:`Prevents its state from changing.`,ar:`تمنع حالته من التغيّر.`}},{text:{en:`Makes it render on a worker thread.`,ar:`تجعله يُعرض في خيط عامل.`}}],explain:{en:"Shallow comparison is the catch: pass an inline object, array or arrow function and the props are never equal, so `memo` costs a comparison and saves nothing.",ar:"المقارنة السطحية هي المأزق: فتمرير كائن أو مصفوفة أو دالة سهمية مضمّنة يجعل الخصائص غير متساوية أبدًا، فتكلّف `memo` مقارنة ولا توفّر شيئًا."}},{id:`i-hw-13`,phase:`how-react-works`,question:{en:`Which tool tells you what actually re-rendered and how long it took?`,ar:`أي أداة تخبرك بما أُعيد عرضه فعلًا وكم استغرق؟`},options:[{text:{en:`The React DevTools Profiler.`,ar:`محلّل React DevTools.`},correct:!0},{text:{en:`The browser's Network tab.`,ar:`تبويب الشبكة في المتصفح.`}},{text:{en:"`console.log` in the render body.",ar:"`console.log` في جسم العرض."}},{text:{en:`The bundle analyser.`,ar:`محلّل الحزمة.`}}],explain:{en:`Guessing at performance almost always targets the wrong component. The Profiler shows the commit, what rendered, and why.`,ar:`تخمين الأداء يستهدف المكوّن الخطأ في الغالب. أما المحلّل فيُظهر التثبيت وما عُرض ولماذا.`}},{id:`i-hw-14`,phase:`how-react-works`,question:{en:"Why is `<Card>{expensiveTree}</Card>` cheaper than `<Card />` rendering the tree itself?",ar:"لماذا تُعدّ `<Card>{expensiveTree}</Card>` أرخص من `<Card />` التي تعرض الشجرة بنفسها؟"},options:[{text:{en:`The tree is created by the parent, so Card's own state changes cannot re-render it.`,ar:`لأن الأب هو من ينشئ الشجرة، فلا تستطيع تغيّرات حالة Card إعادة عرضها.`},correct:!0},{text:{en:"`children` are memoised automatically.",ar:"لأن `children` تُخزَّن تلقائيًا."}},{text:{en:`JSX passed as children is lazily evaluated.`,ar:`لأن JSX الممرّرة كأبناء تُقيَّم بكسل.`}},{text:{en:`It is not cheaper — they are identical.`,ar:`ليست أرخص — فهما متطابقتان.`}}],explain:{en:"The element object already exists before `Card` renders. `Card` just places it, so a state change inside `Card` re-renders only `Card`.",ar:"كائن العنصر موجود قبل أن يُعرض `Card`. و `Card` يضعه فحسب، فتغيّر الحالة داخل `Card` يُعيد عرض `Card` وحده."}},{id:`i-hw-15`,phase:`how-react-works`,question:{en:`What is the "virtual DOM"?`,ar:`ما هو «DOM الافتراضي»؟`},options:[{text:{en:`A lightweight JavaScript description of the UI, kept in memory.`,ar:`وصف جافاسكربت خفيف للواجهة يُحفظ في الذاكرة.`},correct:!0},{text:{en:`A second browser DOM running in a worker.`,ar:`DOM ثانٍ للمتصفح يعمل في خيط عامل.`}},{text:{en:`A cache of rendered HTML strings.`,ar:`ذاكرة مؤقتة لنصوص HTML المعروضة.`}},{text:{en:`The shadow DOM.`,ar:`DOM الظلّي.`}}],explain:{en:`Plain objects, cheap to create and compare. The real DOM is only touched for the differences found between two of these trees.`,ar:`كائنات عادية رخيصة الإنشاء والمقارنة. ولا يُلمس DOM الحقيقي إلا للفروق المكتشفة بين شجرتين منها.`}},{id:`i-hw-16`,phase:`how-react-works`,question:{en:`Does calling a setter always cause a re-render?`,ar:`هل استدعاء دالة الضبط يسبّب إعادة عرض دائمًا؟`},options:[{text:{en:"No — React bails out if the value is identical by `Object.is`.",ar:"لا — تنسحب رياكت إذا كانت القيمة مطابقة وفق `Object.is`."},correct:!0},{text:{en:`Yes, always, without exception.`,ar:`نعم دائمًا وبلا استثناء.`}},{text:{en:`Only in production builds.`,ar:`في بنى الإنتاج فقط.`}},{text:{en:`Only if the component is memoised.`,ar:`فقط إذا كان المكوّن مخزّنًا.`}}],explain:{en:"Which is why `setUser({ ...user })` with no actual change still re-renders — a new object is never `Object.is`-equal to the old one.",ar:"ولهذا فـ `setUser({ ...user })` دون تغيير فعلي تُعيد العرض رغم ذلك — فالكائن الجديد لا يساوي القديم أبدًا وفق `Object.is`."}},{id:`i-hw-17`,phase:`how-react-works`,question:{en:`Where should you look first when a page feels slow to type in?`,ar:`أين تبحث أولًا حين تبدو الصفحة بطيئة أثناء الكتابة؟`},options:[{text:{en:`How high in the tree the input's state lives.`,ar:`إلى أي ارتفاع في الشجرة تعيش حالة الحقل.`},correct:!0},{text:{en:`The size of the CSS bundle.`,ar:`حجم حزمة CSS.`}},{text:{en:`The number of files in the project.`,ar:`عدد الملفات في المشروع.`}},{text:{en:`Whether TypeScript is enabled.`,ar:`ما إذا كان تايب سكربت مفعّلًا.`}}],explain:{en:`A keystroke that sets state at the root re-renders the whole page on every letter. Moving that state into the input's own component usually fixes it outright.`,ar:`ضغطة مفتاح تضبط الحالة عند الجذر تُعيد عرض الصفحة كلها مع كل حرف. ونقل تلك الحالة إلى مكوّن الحقل نفسه يحلّ المشكلة تمامًا في الغالب.`}},{id:`i-hw-18`,phase:`how-react-works`,question:{en:`What does React do when two sibling elements swap but keep the same keys?`,ar:`ماذا تفعل رياكت حين يتبادل عنصران شقيقان الموضع مع بقاء مفاتيحهما؟`},options:[{text:{en:`Moves the existing DOM nodes instead of rebuilding them.`,ar:`تنقل عقد DOM الموجودة بدل إعادة بنائها.`},correct:!0},{text:{en:`Destroys both and creates them again.`,ar:`تهدم كليهما وتنشئهما من جديد.`}},{text:{en:`Warns about duplicate keys.`,ar:`تُحذّر من تكرار المفاتيح.`}},{text:{en:`Ignores the change until the next commit.`,ar:`تتجاهل التغيير حتى التثبيت التالي.`}}],explain:{en:`Stable keys let React recognise the same element in a new position, so focus, scroll and input values travel with the item rather than the slot.`,ar:`تتيح المفاتيح الثابتة لرياكت التعرّف على العنصر نفسه في موضع جديد، فينتقل التركيز والتمرير وقيم الحقول مع العنصر لا مع الخانة.`}},{id:`i-ts-01`,phase:`typescript-with-react`,question:{en:`Which type accepts anything React can render, including strings and arrays?`,ar:`أي نوع يقبل كل ما تستطيع رياكت عرضه بما في ذلك النصوص والمصفوفات؟`},options:[{text:{en:"`ReactNode`",ar:"`ReactNode`"},correct:!0},{text:{en:"`ReactElement`",ar:"`ReactElement`"}},{text:{en:"`JSX.Element`",ar:"`JSX.Element`"}},{text:{en:"`HTMLElement`",ar:"`HTMLElement`"}}],explain:{en:"`ReactNode` is the wide one — elements, strings, numbers, arrays, `null`. `ReactElement` and `JSX.Element` only accept a single element, which rejects plain text children.",ar:"`ReactNode` هو الأوسع — عناصر ونصوص وأرقام ومصفوفات و `null`. أما `ReactElement` و `JSX.Element` فيقبلان عنصرًا واحدًا فقط، ما يرفض الأبناء النصيّين."}},{id:`i-ts-02`,phase:`typescript-with-react`,question:{en:`How do you type an input's change handler?`,ar:`كيف تُنمّط معالج تغيير حقل إدخال؟`},options:[{text:{en:"`(e: React.ChangeEvent<HTMLInputElement>) => void`",ar:"`(e: React.ChangeEvent<HTMLInputElement>) => void`"},correct:!0},{text:{en:"`(e: Event) => void`",ar:"`(e: Event) => void`"}},{text:{en:"`(e: any) => void`",ar:"`(e: any) => void`"}},{text:{en:"`(e: React.MouseEvent) => void`",ar:"`(e: React.MouseEvent) => void`"}}],explain:{en:"The generic parameter is what makes `e.target.value` a `string` rather than an error. Inline handlers usually infer it for free — you only annotate when the function is separate.",ar:"معامل النوع العام هو ما يجعل `e.target.value` نصًا بدل خطأ. والمعالجات المضمّنة تستنتجه مجانًا عادةً — ولا تُصرّح به إلا حين تكون الدالة منفصلة."}},{id:`i-ts-03`,phase:`typescript-with-react`,question:{en:"When must you pass a type argument to `useState`?",ar:"متى يجب تمرير وسيط نوع إلى `useState`؟"},options:[{text:{en:`When the initial value does not describe every future value.`,ar:`حين لا تصف القيمة الابتدائية كل القيم المستقبلية.`},correct:!0},{text:{en:`Always, for every piece of state.`,ar:`دائمًا ومع كل جزء من الحالة.`}},{text:{en:`Only for primitives.`,ar:`مع القيم الأولية فقط.`}},{text:{en:`Never — inference always works.`,ar:`أبدًا — فالاستنتاج ينجح دائمًا.`}}],explain:{en:"`useState(0)` infers `number` perfectly. `useState(null)` infers `null`, so a later user object is rejected — that is when you write `useState<User | null>(null)`.",ar:"تستنتج `useState(0)` النوع `number` بدقّة. أما `useState(null)` فتستنتج `null` فيُرفض كائن المستخدم لاحقًا — وعندها تكتب `useState<User | null>(null)`."}},{id:`i-ts-04`,phase:`typescript-with-react`,question:{en:'What does `Omit<ButtonProps, "onClick">` produce?',ar:'ماذا يُنتج `Omit<ButtonProps, "onClick">`؟'},options:[{text:{en:"`ButtonProps` with the `onClick` key removed.",ar:"`ButtonProps` بعد حذف المفتاح `onClick`."},correct:!0},{text:{en:"Only the `onClick` key.",ar:"المفتاح `onClick` فقط."}},{text:{en:"`ButtonProps` with `onClick` made optional.",ar:"`ButtonProps` مع جعل `onClick` اختياريًا."}},{text:{en:`A runtime object with the key deleted.`,ar:`كائنًا وقت التشغيل بعد حذف المفتاح.`}}],explain:{en:"Utility types are compile-time only — nothing is deleted at runtime. `Pick` is the inverse, keeping just the keys you name.",ar:"الأنواع المساعدة وقت التصريف فقط — فلا يُحذف شيء وقت التشغيل. و `Pick` عكسها، إذ تُبقي المفاتيح التي تُسمّيها فقط."}},{id:`i-ts-05`,phase:`typescript-with-react`,question:{en:`How do you make a prop optional?`,ar:`كيف تجعل خاصية اختيارية؟`},options:[{text:{en:"`label?: string`",ar:"`label?: string`"},correct:!0},{text:{en:"`label: string | optional`",ar:"`label: string | optional`"}},{text:{en:"`optional label: string`",ar:"`optional label: string`"}},{text:{en:"`label!: string`",ar:"`label!: string`"}}],explain:{en:"The `?` makes the type `string | undefined`. Note `label!: string` means the opposite — a non-null assertion telling the compiler to trust you.",ar:"تجعل `?` النوع `string | undefined`. ولاحظ أن `label!: string` تعني العكس — تأكيدًا بعدم العدمية يطلب من المُصرِّف أن يثق بك."}},{id:`i-ts-06`,phase:`typescript-with-react`,question:{en:`What is a discriminated union useful for in props?`,ar:`فيمَ يفيد الاتحاد المُميَّز في الخصائص؟`},options:[{text:{en:`Making impossible prop combinations fail to compile.`,ar:`جعل تركيبات الخصائص المستحيلة تفشل في التصريف.`},correct:!0},{text:{en:`Merging two component types into one.`,ar:`دمج نوعَي مكوّن في واحد.`}},{text:{en:`Making every prop optional at once.`,ar:`جعل كل الخصائص اختيارية دفعة واحدة.`}},{text:{en:`Generating runtime validation.`,ar:`توليد تحقّق وقت التشغيل.`}}],explain:{en:'A shared literal field lets the compiler narrow: `{ status: "error"; message: string } | { status: "ok"; data: User }` makes reading `message` on a success impossible.',ar:'يتيح حقل حرفي مشترك للمُصرِّف التضييق: فـ `{ status: "error"; message: string } | { status: "ok"; data: User }` تجعل قراءة `message` في حالة النجاح مستحيلة.'}},{id:`i-ts-07`,phase:`typescript-with-react`,question:{en:`How do you type a ref to a DOM input?`,ar:`كيف تُنمّط مرجعًا لحقل إدخال في DOM؟`},options:[{text:{en:"`useRef<HTMLInputElement>(null)`",ar:"`useRef<HTMLInputElement>(null)`"},correct:!0},{text:{en:"`useRef<HTMLInputElement>()`",ar:"`useRef<HTMLInputElement>()`"}},{text:{en:"`useRef(HTMLInputElement)`",ar:"`useRef(HTMLInputElement)`"}},{text:{en:"`useRef<any>(null)`",ar:"`useRef<any>(null)`"}}],explain:{en:"The `null` start matches reality: the node does not exist until after the first commit, which is why `ref.current?.focus()` needs the optional chain.",ar:"البداية بـ `null` تطابق الواقع: فالعقدة غير موجودة إلا بعد أول تثبيت، ولهذا تحتاج `ref.current?.focus()` إلى الوصول الآمن."}},{id:`i-ts-08`,phase:`typescript-with-react`,question:{en:"Why write `<T,>` in a generic arrow component inside a `.tsx` file?",ar:"لماذا تُكتب `<T,>` في مكوّن سهمي عام داخل ملف `.tsx`؟"},options:[{text:{en:"The trailing comma stops the parser reading `<T>` as JSX.",ar:"لأن الفاصلة اللاحقة تمنع المحلّل من قراءة `<T>` كـ JSX."},correct:!0},{text:{en:`It declares two type parameters.`,ar:`لأنها تُصرّح بمعاملَي نوع.`}},{text:{en:`It makes the type optional.`,ar:`لأنها تجعل النوع اختياريًا.`}},{text:{en:`It is a formatting convention only.`,ar:`لأنها عرف تنسيقي فقط.`}}],explain:{en:"A pure `.ts` file has no ambiguity. In `.tsx` the comma disambiguates — or use `function List<T>(...)`, which never has the problem.",ar:"لا لبس في ملف `.ts` الخالص. أما في `.tsx` فالفاصلة تُزيل اللبس — أو استخدم `function List<T>(...)` التي لا تواجه المشكلة أصلًا."}},{id:`i-ts-09`,phase:`typescript-with-react`,question:{en:"What is the practical difference between `type` and `interface` for props?",ar:"ما الفرق العملي بين `type` و `interface` للخصائص؟"},options:[{text:{en:"Very little; `type` also handles unions and intersections.",ar:"فرق ضئيل، لكن `type` تتعامل أيضًا مع الاتحادات والتقاطعات."},correct:!0},{text:{en:"`interface` is faster at runtime.",ar:"`interface` أسرع وقت التشغيل."}},{text:{en:"`type` cannot describe objects.",ar:"`type` لا تستطيع وصف الكائنات."}},{text:{en:"Only `interface` works with React.",ar:"`interface` وحدها تعمل مع رياكت."}}],explain:{en:"Neither exists at runtime. `interface` can be re-opened and merged, `type` can express a union — pick one per codebase and stay consistent.",ar:"لا وجود لأيّهما وقت التشغيل. يمكن إعادة فتح `interface` ودمجها، وتستطيع `type` التعبير عن اتحاد — اختر واحدة لكل مشروع والتزم بها."}},{id:`i-ts-10`,phase:`typescript-with-react`,question:{en:"How do you accept every native button attribute in your own `Button`?",ar:"كيف تقبل كل خصائص الزر الأصلية في مكوّن `Button` خاص بك؟"},options:[{text:{en:'Extend `React.ComponentProps<"button">`.',ar:'وسّع `React.ComponentProps<"button">`.'},correct:!0},{text:{en:"Type the props as `any`.",ar:"نمّط الخصائص كـ `any`."}},{text:{en:`List every attribute by hand.`,ar:`اسرد كل خاصية يدويًا.`}},{text:{en:"Use `Record<string, unknown>`.",ar:"استخدم `Record<string, unknown>`."}}],explain:{en:"You inherit `disabled`, `type`, `aria-*` and the rest, then spread them onto the element. Combine with `Omit` when you want to redefine one.",ar:"ترث `disabled` و `type` و `aria-*` وغيرها ثم تنشرها على العنصر. وادمجها مع `Omit` حين تريد إعادة تعريف إحداها."}},{id:`i-ts-11`,phase:`typescript-with-react`,question:{en:'What does `as const` do to `{ status: "ok" }`?',ar:'ماذا تفعل `as const` بـ `{ status: "ok" }`؟'},options:[{text:{en:'Narrows `status` to the literal `"ok"` instead of `string`.',ar:'تُضيّق `status` إلى القيمة الحرفية `"ok"` بدل `string`.'},correct:!0},{text:{en:`Freezes the object at runtime.`,ar:`تُجمّد الكائن وقت التشغيل.`}},{text:{en:`Makes every key optional.`,ar:`تجعل كل مفتاح اختياريًا.`}},{text:{en:`Converts it to an enum.`,ar:`تُحوّله إلى تعداد.`}}],explain:{en:"Literal narrowing is what makes discriminated unions work. It is a type-level assertion, so nothing is actually frozen — use `Object.freeze` for that.",ar:"تضييق القيم الحرفية هو ما يجعل الاتحادات المُميَّزة تعمل. وهو تأكيد على مستوى النوع فلا شيء يُجمَّد فعليًا — استخدم `Object.freeze` لذلك."}},{id:`i-ts-12`,phase:`typescript-with-react`,question:{en:`Which is the weakest way to silence a type error?`,ar:`ما أضعف طريقة لإسكات خطأ نوع؟`},options:[{text:{en:"Casting to `any`.",ar:"التحويل إلى `any`."},correct:!0},{text:{en:`Narrowing with a type guard.`,ar:`التضييق بحارس نوع.`}},{text:{en:`Adding the missing union member.`,ar:`إضافة عضو الاتحاد الناقص.`}},{text:{en:`Making the prop optional.`,ar:`جعل الخاصية اختيارية.`}}],explain:{en:"`any` switches checking off for everything downstream, so the error reappears later as a runtime crash. `unknown` is the honest escape hatch — it forces you to narrow.",ar:"تُوقف `any` الفحص لكل ما يتبعها، فيظهر الخطأ لاحقًا كانهيار وقت التشغيل. أما `unknown` فهي المخرج الأمين — إذ تُجبرك على التضييق."}},{id:`i-ts-13`,phase:`typescript-with-react`,question:{en:"How is a generic `<List<T> />` more useful than one typed to `unknown[]`?",ar:"كيف يكون `<List<T> />` العام أنفع من واحد مُنمَّط بـ `unknown[]`؟"},options:[{text:{en:`The item type flows into the render callback at each call site.`,ar:`لأن نوع العنصر ينساب إلى دالة العرض في كل موضع استدعاء.`},correct:!0},{text:{en:`It renders faster.`,ar:`لأنه يُعرض أسرع.`}},{text:{en:`It allows more items.`,ar:`لأنه يسمح بعناصر أكثر.`}},{text:{en:`It removes the need for keys.`,ar:`لأنه يُلغي الحاجة إلى المفاتيح.`}}],explain:{en:"With `unknown[]` every callback has to cast. With a generic, `renderItem` receives a fully typed `User` or `Task` automatically.",ar:"مع `unknown[]` تحتاج كل دالة رد نداء إلى تحويل. أما مع النوع العام فتستقبل `renderItem` كائن `User` أو `Task` مُنمَّطًا بالكامل تلقائيًا."}},{id:`i-ts-14`,phase:`typescript-with-react`,question:{en:`What should the return type of a component usually be?`,ar:`ماذا يجب أن يكون نوع إعادة المكوّن عادةً؟`},options:[{text:{en:`Left to inference — you rarely need to annotate it.`,ar:`متروكًا للاستنتاج — فنادرًا ما تحتاج التصريح به.`},correct:!0},{text:{en:"`React.FC` on every component.",ar:"`React.FC` على كل مكوّن."}},{text:{en:"`void`",ar:"`void`"}},{text:{en:"`any`",ar:"`any`"}}],explain:{en:"Inference already gives you the right type, and `React.FC` fell out of favour because it complicates generics and once forced an implicit `children`.",ar:"يمنحك الاستنتاج النوع الصحيح أصلًا، وقد تراجع استخدام `React.FC` لأنه يُعقّد الأنواع العامة وكان يفرض `children` ضمنيًا في السابق."}},{id:`i-ts-15`,phase:`typescript-with-react`,question:{en:"Why does `verbatimModuleSyntax` want `import type { User }` rather than `import { User }`?",ar:"لماذا يطلب `verbatimModuleSyntax` كتابة `import type { User }` بدل `import { User }`؟"},options:[{text:{en:`It marks the import as erasable, so the bundler drops it cleanly.`,ar:`لأنه يُعلّم الاستيراد كقابل للمحو فيحذفه المُجمِّع بنظافة.`},correct:!0},{text:{en:`Type imports load faster.`,ar:`لأن استيرادات الأنواع تُحمّل أسرع.`}},{text:{en:`It is required for all named imports.`,ar:`لأنه مطلوب لكل الاستيرادات المُسمّاة.`}},{text:{en:`It enables tree shaking of values.`,ar:`لأنه يُفعّل هزّ الشجرة للقيم.`}}],explain:{en:`Without the marker a bundler cannot always tell whether the import has a runtime side effect, so it may keep a module you only needed for its types.`,ar:`بدون هذه العلامة قد لا يستطيع المُجمِّع تحديد ما إذا كان للاستيراد أثر وقت التشغيل، فيُبقي وحدةً لم تكن تحتاجها إلا لأنواعها.`}},{id:`i-tl-01`,phase:`tooling-and-setup`,question:{en:`Why does the Vite dev server start almost instantly on a large project?`,ar:`لماذا يبدأ خادم تطوير Vite فورًا تقريبًا في مشروع كبير؟`},options:[{text:{en:`It serves native ES modules and only transforms files the browser asks for.`,ar:`لأنه يقدّم وحدات ES الأصلية ولا يحوّل إلا الملفات التي يطلبها المتصفح.`},correct:!0},{text:{en:`It bundles the whole app ahead of time.`,ar:`لأنه يحزم التطبيق كله مسبقًا.`}},{text:{en:`It skips TypeScript entirely.`,ar:`لأنه يتخطّى تايب سكربت بالكامل.`}},{text:{en:`It runs the app on a remote server.`,ar:`لأنه يشغّل التطبيق على خادم بعيد.`}}],explain:{en:`Nothing is bundled up front in development, so start-up barely grows with project size. The production build still bundles properly.`,ar:`لا شيء يُحزَم مسبقًا في التطوير، فلا ينمو زمن البدء تقريبًا مع حجم المشروع. أما بناء الإنتاج فما زال يحزم كما ينبغي.`}},{id:`i-tl-02`,phase:`tooling-and-setup`,question:{en:`Which environment variable is exposed to the browser by Vite?`,ar:`أي متغيّر بيئة يكشفه Vite للمتصفح؟`},options:[{text:{en:"`VITE_API_URL`",ar:"`VITE_API_URL`"},correct:!0},{text:{en:"`API_URL`",ar:"`API_URL`"}},{text:{en:"`SECRET_KEY`",ar:"`SECRET_KEY`"}},{text:{en:`All of them.`,ar:`كلها.`}}],explain:{en:"Only the `VITE_` prefix is inlined into the client bundle. That prefix is a safety gate, not a security feature — anything it exposes is readable by anyone.",ar:"البادئة `VITE_` وحدها تُدرَج في حزمة العميل. وهي بوابة أمان لا ميزة أمنية — فكل ما تكشفه يستطيع أي شخص قراءته."}},{id:`i-tl-03`,phase:`tooling-and-setup`,question:{en:`Where can you safely keep a private API secret in a client-only React app?`,ar:`أين يمكنك حفظ سرّ واجهة برمجية خاص بأمان في تطبيق رياكت يعمل على العميل فقط؟`},options:[{text:{en:`Nowhere — it must live on a server you control.`,ar:`في لا مكان — فيجب أن يعيش على خادم تتحكّم فيه.`},correct:!0},{text:{en:"In `.env` with the `VITE_` prefix.",ar:"في `.env` مع البادئة `VITE_`."}},{text:{en:"In `localStorage` at build time.",ar:"في `localStorage` وقت البناء."}},{text:{en:"In a `.env` file listed in `.gitignore`.",ar:"في ملف `.env` مُدرج في `.gitignore`."}}],explain:{en:`Every value in a frontend build ships to the browser. Keeping the file out of git hides it from your repo, not from anyone who opens DevTools.`,ar:`كل قيمة في بناء الواجهة تصل إلى المتصفح. وإبقاء الملف خارج git يُخفيه عن مستودعك لا عمّن يفتح أدوات المطوّر.`}},{id:`i-tl-04`,phase:`tooling-and-setup`,question:{en:`What is the point of separating ESLint and Prettier?`,ar:`ما الغاية من الفصل بين ESLint و Prettier؟`},options:[{text:{en:`One catches likely bugs, the other settles formatting.`,ar:`أحدهما يلتقط الأخطاء المحتملة والآخر يحسم التنسيق.`},correct:!0},{text:{en:`Prettier is only for CSS.`,ar:`لأن Prettier للـ CSS فقط.`}},{text:{en:`ESLint cannot read TypeScript.`,ar:`لأن ESLint لا تقرأ تايب سكربت.`}},{text:{en:`They do the same job; one is a backup.`,ar:`لأنهما يؤدّيان العمل نفسه وأحدهما احتياطي.`}}],explain:{en:"Lint rules like `rules-of-hooks` and `exhaustive-deps` catch real defects. Formatting is not a correctness question, so it should never be argued about in review.",ar:"قواعد الفحص مثل `rules-of-hooks` و `exhaustive-deps` تلتقط عيوبًا حقيقية. أما التنسيق فليس مسألة صحّة، فلا ينبغي الجدال حوله في المراجعة إطلاقًا."}},{id:`i-tl-05`,phase:`tooling-and-setup`,question:{en:"Which ESLint rule catches a `useEffect` that reads a value it does not list?",ar:"أي قاعدة ESLint تلتقط `useEffect` يقرأ قيمة لم يُدرجها؟"},options:[{text:{en:"`react-hooks/exhaustive-deps`",ar:"`react-hooks/exhaustive-deps`"},correct:!0},{text:{en:"`no-unused-vars`",ar:"`no-unused-vars`"}},{text:{en:"`react/jsx-key`",ar:"`react/jsx-key`"}},{text:{en:"`no-undef`",ar:"`no-undef`"}}],explain:{en:`It is the rule that prevents stale closures. Disabling it line by line is usually a sign the effect should be restructured, not silenced.`,ar:`إنها القاعدة التي تمنع الإغلاقات القديمة. وتعطيلها سطرًا بسطر يدلّ عادةً على أن التأثير يحتاج إعادة هيكلة لا إسكاتًا.`}},{id:`i-tl-06`,phase:`tooling-and-setup`,question:{en:"What advantage does organising by feature have over `components/`, `hooks/`, `utils/`?",ar:"ما ميزة التنظيم حسب الميزة على `components/` و `hooks/` و `utils/`؟"},options:[{text:{en:`Everything one feature needs sits together, so it can be changed or deleted as a unit.`,ar:`أن كل ما تحتاجه ميزة يجتمع معًا، فيمكن تغييرها أو حذفها كوحدة.`},correct:!0},{text:{en:`It produces smaller bundles automatically.`,ar:`أنه يُنتج حزمًا أصغر تلقائيًا.`}},{text:{en:`It is required by Vite.`,ar:`أن Vite يفرضه.`}},{text:{en:`It removes the need for imports.`,ar:`أنه يُلغي الحاجة إلى الاستيرادات.`}}],explain:{en:`Type folders scatter one feature across four directories. Feature folders keep the blast radius of a change in one place — and shared code still gets a common folder.`,ar:`مجلدات النوع تُشتّت الميزة الواحدة عبر أربعة مجلدات. أما مجلدات الميزات فتُبقي نطاق أي تغيير في مكان واحد — ويبقى للكود المشترك مجلد عام.`}},{id:`i-tl-07`,phase:`tooling-and-setup`,question:{en:"What does `npm run build` typically do that `npm run dev` does not?",ar:"ماذا يفعل `npm run build` عادةً ولا يفعله `npm run dev`؟"},options:[{text:{en:"Type-check, minify and emit hashed static files to `dist/`.",ar:"يفحص الأنواع ويُصغّر ويُخرج ملفات ثابتة بأسماء مُجزّأة إلى `dist/`."},correct:!0},{text:{en:`Install dependencies.`,ar:`يثبّت الاعتماديات.`}},{text:{en:`Start a server on port 5173.`,ar:`يبدأ خادمًا على المنفذ 5173.`}},{text:{en:`Run the test suite.`,ar:`يُشغّل مجموعة الاختبارات.`}}],explain:{en:`Content-hashed filenames are what let a CDN cache assets forever — a changed file gets a new name, so there is nothing stale to invalidate.`,ar:`أسماء الملفات المُجزّأة بالمحتوى هي ما يتيح لشبكة التوزيع تخزين الأصول إلى الأبد — فالملف المتغيّر يأخذ اسمًا جديدًا، فلا يبقى قديم يُبطَل.`}},{id:`i-tl-08`,phase:`tooling-and-setup`,question:{en:"Why should `node_modules` be in `.gitignore`?",ar:"لماذا يجب وضع `node_modules` في `.gitignore`؟"},options:[{text:{en:`It is huge and fully reproducible from the lockfile.`,ar:`لأنه ضخم وقابل لإعادة الإنتاج بالكامل من ملف القفل.`},correct:!0},{text:{en:`It contains secrets.`,ar:`لأنه يحوي أسرارًا.`}},{text:{en:`Git cannot store binary files.`,ar:`لأن git لا تستطيع تخزين الملفات الثنائية.`}},{text:{en:`It changes the build output.`,ar:`لأنه يُغيّر ناتج البناء.`}}],explain:{en:`The lockfile is the thing to commit — it pins exact versions so every machine and CI run installs an identical tree.`,ar:`ملف القفل هو ما يجب إيداعه — فهو يثبّت الإصدارات الدقيقة ليُثبّت كل جهاز وكل تشغيل للتكامل المستمر شجرةً متطابقة.`}},{id:`i-tl-09`,phase:`tooling-and-setup`,question:{en:"What does a path alias like `@/components` buy you?",ar:"ماذا يمنحك اسم مسار مستعار مثل `@/components`؟"},options:[{text:{en:"Imports that survive moving a file, instead of `../../../`.",ar:"استيرادات تصمد عند نقل الملف بدل `../../../`."},correct:!0},{text:{en:`Faster module resolution at runtime.`,ar:`حلّ وحدات أسرع وقت التشغيل.`}},{text:{en:`Automatic code splitting.`,ar:`تقسيم كود تلقائيًا.`}},{text:{en:`Smaller bundles.`,ar:`حزمًا أصغر.`}}],explain:{en:"It has to be configured twice — once in the bundler so it resolves, once in `tsconfig` `paths` so the editor follows it.",ar:"يجب إعداده مرتين — مرة في المُجمِّع ليُحَلّ، ومرة في `paths` داخل `tsconfig` ليتبعه المحرّر."}},{id:`i-tl-10`,phase:`tooling-and-setup`,question:{en:`Which is the better commit message?`,ar:`أي رسالة إيداع أفضل؟`},options:[{text:{en:"`fix: prevent duplicate submit when the network is slow`",ar:"`fix: منع الإرسال المكرّر عند بطء الشبكة`"},correct:!0},{text:{en:"`fixes`",ar:"`إصلاحات`"}},{text:{en:"`update code`",ar:"`تحديث الكود`"}},{text:{en:"`wip`",ar:"`عمل جارٍ`"}}],explain:{en:"A message should say what changed and why, because the audience is whoever runs `git log` in six months trying to understand a line you wrote.",ar:"يجب أن تقول الرسالة ما تغيّر ولماذا، فجمهورها من سيُشغّل `git log` بعد ستة أشهر محاولًا فهم سطر كتبته."}},{id:`i-tl-11`,phase:`tooling-and-setup`,question:{en:`Why does a production build keep a separate chunk for a large editor component?`,ar:`لماذا يُبقي بناء الإنتاج حزمة منفصلة لمكوّن محرّر كبير؟`},options:[{text:{en:`So visitors who never open it never download it.`,ar:`كي لا يُنزّله من لا يفتحه أبدًا.`},correct:!0},{text:{en:`Because large files cannot be minified.`,ar:`لأن الملفات الكبيرة لا يمكن تصغيرها.`}},{text:{en:`To keep the CSS separate.`,ar:`لإبقاء CSS منفصلًا.`}},{text:{en:`Chunking is only for images.`,ar:`لأن التقسيم للصور فقط.`}}],explain:{en:"A dynamic `import()` marks the split point. The cost moves from every first visit to only the visits that actually need it.",ar:"استيراد `import()` الديناميكي يُعلّم نقطة التقسيم. فتنتقل التكلفة من كل زيارة أولى إلى الزيارات التي تحتاجه فعلًا فقط."}},{id:`i-tl-12`,phase:`tooling-and-setup`,question:{en:`What is the purpose of a lockfile?`,ar:`ما الغرض من ملف القفل؟`},options:[{text:{en:`Pinning the exact resolved version of every dependency.`,ar:`تثبيت الإصدار الدقيق المُحلّ لكل اعتمادية.`},correct:!0},{text:{en:`Preventing others from editing the project.`,ar:`منع الآخرين من تعديل المشروع.`}},{text:{en:`Listing which files are read-only.`,ar:`سرد الملفات للقراءة فقط.`}},{text:{en:`Caching the build output.`,ar:`تخزين ناتج البناء مؤقتًا.`}}],explain:{en:'`package.json` says `^19.2.0`, which is a range. The lockfile records the one version actually installed, so "works on my machine" stops being a mystery.',ar:"يقول `package.json` مثلًا `^19.2.0` وهو نطاق. أما ملف القفل فيسجّل الإصدار الوحيد المثبَّت فعلًا، فتتوقّف عبارة «يعمل على جهازي» عن كونها لغزًا."}},{id:`i-tl-13`,phase:`tooling-and-setup`,question:{en:"What belongs in `devDependencies` rather than `dependencies`?",ar:"ما الذي ينتمي إلى `devDependencies` بدل `dependencies`؟"},options:[{text:{en:`Anything only needed to build or test, such as Vite and the test runner.`,ar:`كل ما يُحتاج للبناء أو الاختبار فقط مثل Vite ومُشغّل الاختبارات.`},correct:!0},{text:{en:`Anything under 100 kB.`,ar:`كل ما حجمه أقل من 100 كيلوبايت.`}},{text:{en:`React itself.`,ar:`رياكت نفسها.`}},{text:{en:`Nothing — the split is cosmetic.`,ar:`لا شيء — فالتقسيم شكلي.`}}],explain:{en:`For a bundled frontend the split does not change what ships — the bundler decides that. It matters for install time in CI and for anyone consuming your package.`,ar:`في واجهة مُجمَّعة لا يُغيّر هذا التقسيم ما يُشحَن — فالمُجمِّع هو من يقرّر. لكنه يهمّ لزمن التثبيت في التكامل المستمر ولمن يستهلك حزمتك.`}},{id:`i-tl-14`,phase:`tooling-and-setup`,question:{en:"Why work on a branch rather than committing straight to `main`?",ar:"لماذا تعمل على فرع بدل الإيداع مباشرةً في `main`؟"},options:[{text:{en:"Work can be reviewed and reverted as a unit without destabilising `main`.",ar:"لأن العمل يمكن مراجعته والتراجع عنه كوحدة دون زعزعة `main`."},correct:!0},{text:{en:`Branches make the build faster.`,ar:`لأن الفروع تُسرّع البناء.`}},{text:{en:`Git requires it.`,ar:`لأن git تفرض ذلك.`}},{text:{en:`It compresses the repository.`,ar:`لأنها تضغط المستودع.`}}],explain:{en:"A branch keeps `main` deployable at all times, and a pull request is where review, CI and discussion happen before anything lands.",ar:"يُبقي الفرع `main` قابلًا للنشر في كل وقت، وطلب الدمج هو موضع المراجعة والتكامل المستمر والنقاش قبل أن يصل أي شيء."}},{id:`i-tl-15`,phase:`tooling-and-setup`,question:{en:`A deployed single-page app 404s when a deep link is refreshed. What is missing?`,ar:`تطبيق صفحة واحدة منشور يُعطي 404 عند تحديث رابط عميق. ما الناقص؟`},options:[{text:{en:"A host rewrite sending unknown paths to `index.html`.",ar:"إعادة كتابة على المستضيف تُرسل المسارات المجهولة إلى `index.html`."},correct:!0},{text:{en:"A missing `base` in the Vite config.",ar:"قيمة `base` مفقودة في إعداد Vite."}},{text:{en:`A service worker.`,ar:`عامل خدمة.`}},{text:{en:`Server-side rendering.`,ar:`عرض من جهة الخادم.`}}],explain:{en:`The route exists only in the client router. The server has no such file, so every path has to fall back to the one HTML entry point.`,ar:`المسار موجود في موجّه العميل فقط. ولا يملك الخادم ملفًا كهذا، فيجب أن يرتدّ كل مسار إلى نقطة دخول HTML الوحيدة.`}},{id:`i-st-01`,phase:`styling`,question:{en:`Why do long utility class strings not become unmaintainable in React?`,ar:`لماذا لا تصبح سلاسل أصناف الأدوات الطويلة عصيّة على الصيانة في رياكت؟`},options:[{text:{en:`The component is the unit of reuse, so the string is written once.`,ar:`لأن المكوّن هو وحدة إعادة الاستخدام، فتُكتب السلسلة مرة واحدة.`},correct:!0},{text:{en:`Tailwind shortens them at build time.`,ar:`لأن Tailwind يختصرها وقت البناء.`}},{text:{en:`The classes are generated automatically.`,ar:`لأن الأصناف تُولَّد تلقائيًا.`}},{text:{en:`They are hidden by the formatter.`,ar:`لأن المنسّق يُخفيها.`}}],explain:{en:"You never repeat the string — you repeat `<Button />`. That is why utility CSS and component frameworks fit together so well.",ar:"أنت لا تكرّر السلسلة بل تكرّر `<Button />`. ولهذا يتلاءم CSS الأدواتي مع أطر المكوّنات إلى هذا الحدّ."}},{id:`i-st-02`,phase:`styling`,question:{en:`What does a CSS Module do to a class name?`,ar:`ماذا تفعل وحدة CSS باسم الصنف؟`},options:[{text:{en:`Rewrites it to a locally unique name at build time.`,ar:`تُعيد كتابته إلى اسم فريد محليًا وقت البناء.`},correct:!0},{text:{en:`Applies it only inside a shadow root.`,ar:`تُطبّقه داخل جذر ظلّي فقط.`}},{text:{en:`Injects it at runtime with JavaScript.`,ar:`تحقنه وقت التشغيل بجافاسكربت.`}},{text:{en:`Nothing — the name is used verbatim.`,ar:`لا شيء — فالاسم يُستخدم حرفيًا.`}}],explain:{en:"`.title` becomes something like `Card_title__x7f2`, so two files can both use `.title` with no collision — and it costs nothing at runtime.",ar:"يصبح `.title` شيئًا مثل `Card_title__x7f2`، فيستطيع ملفان استخدام `.title` دون تصادم — وبلا أي تكلفة وقت التشغيل."}},{id:`i-st-03`,phase:`styling`,question:{en:`What does a headless component library such as Radix give you?`,ar:`ماذا تمنحك مكتبة مكوّنات بلا تنسيق مثل Radix؟`},options:[{text:{en:`Behaviour and accessibility, with the styling left entirely to you.`,ar:`السلوك والإتاحة، مع ترك التنسيق لك بالكامل.`},correct:!0},{text:{en:`A finished visual design system.`,ar:`نظام تصميم بصري جاهز.`}},{text:{en:`A CSS reset.`,ar:`إعادة ضبط لـ CSS.`}},{text:{en:`Server-side rendering.`,ar:`عرضًا من جهة الخادم.`}}],explain:{en:`Focus trapping, keyboard navigation, ARIA wiring and dismiss behaviour are the hard parts. Getting a dialog right by hand is much harder than it looks.`,ar:`حجز التركيز والتنقّل بلوحة المفاتيح وربط ARIA وسلوك الإغلاق هي الأجزاء الصعبة. فبناء حوار صحيح يدويًا أصعب بكثير مما يبدو.`}},{id:`i-st-04`,phase:`styling`,question:{en:"In Tailwind, what does `md:flex` mean?",ar:"في Tailwind ماذا تعني `md:flex`؟"},options:[{text:{en:"Apply `display: flex` from the `md` breakpoint upwards.",ar:"طبّق `display: flex` من نقطة التوقّف `md` فأعلى."},correct:!0},{text:{en:"Apply it only below `md`.",ar:"طبّقها تحت `md` فقط."}},{text:{en:"Apply it only at exactly `md`.",ar:"طبّقها عند `md` بالضبط فقط."}},{text:{en:`Apply it on medium-sized elements.`,ar:`طبّقها على العناصر متوسّطة الحجم.`}}],explain:{en:`Breakpoint prefixes are min-width, so the unprefixed class is the mobile case and each prefix layers on top as the screen grows.`,ar:`بادئات نقاط التوقّف تعمل بأدنى عرض، فالصنف بلا بادئة هو حالة الجوّال وتتراكم كل بادئة فوقه كلما كبرت الشاشة.`}},{id:`i-st-05`,phase:`styling`,question:{en:'Why does `clsx("p-2", isActive && "bg-blue-500")` work well for conditional classes?',ar:'لماذا تنجح `clsx("p-2", isActive && "bg-blue-500")` مع الأصناف الشرطية؟'},options:[{text:{en:`It drops falsy values and joins the rest with spaces.`,ar:`لأنها تحذف القيم falsy وتربط الباقي بمسافات.`},correct:!0},{text:{en:`It resolves Tailwind conflicts.`,ar:`لأنها تحلّ تعارضات Tailwind.`}},{text:{en:`It minifies the class names.`,ar:`لأنها تُصغّر أسماء الأصناف.`}},{text:{en:`It scopes the classes to the component.`,ar:`لأنها تعزل الأصناف داخل المكوّن.`}}],explain:{en:'Without it you get `"p-2 false"` in the DOM. Resolving conflicts between two competing utilities is a different job — that is `tailwind-merge`.',ar:'بدونها تحصل على `"p-2 false"` في DOM. أما حلّ التعارض بين أداتين متنافستين فمهمة أخرى — وهي `tailwind-merge`.'}},{id:`i-st-06`,phase:`styling`,question:{en:"A component sets `p-2` and a caller passes `p-8`. What does `tailwind-merge` do?",ar:"مكوّن يضبط `p-2` ويمرّر المستدعي `p-8`. ماذا تفعل `tailwind-merge`؟"},options:[{text:{en:"Keeps `p-8` and drops the conflicting `p-2`.",ar:"تُبقي `p-8` وتحذف `p-2` المتعارضة."},correct:!0},{text:{en:`Keeps both and lets CSS order decide.`,ar:`تُبقي كليهما وتترك ترتيب CSS يقرّر.`}},{text:{en:`Throws an error.`,ar:`تُطلق خطأً.`}},{text:{en:`Averages the two values.`,ar:`تأخذ متوسّط القيمتين.`}}],explain:{en:`Both classes have equal CSS specificity, so which one wins depends on stylesheet order — unpredictable. Merging resolves it by intent instead.`,ar:`للصنفين خصوصية CSS متساوية، فيعتمد الفائز على ترتيب ورقة الأنماط — وهو غير متوقّع. أما الدمج فيحسمها حسب النيّة.`}},{id:`i-st-07`,phase:`styling`,question:{en:`How is a dark mode toggle usually made to survive a reload without a flash?`,ar:`كيف يُجعل مبدّل الوضع الداكن يصمد بعد إعادة التحميل دون وميض؟`},options:[{text:{en:`Read the stored choice and set the class in a script before first paint.`,ar:`اقرأ الخيار المحفوظ واضبط الصنف في سكربت قبل أول رسم.`},correct:!0},{text:{en:"Set it in a `useEffect` after mount.",ar:"اضبطه في `useEffect` بعد التركيب."}},{text:{en:`Use a CSS transition to hide the change.`,ar:`استخدم انتقال CSS لإخفاء التغيير.`}},{text:{en:`Store it in a cookie only.`,ar:`خزّنه في ملفّ تعريف ارتباط فقط.`}}],explain:{en:`An effect runs after the first paint, so the light theme flashes first. A tiny inline script in the document head runs before anything is drawn.`,ar:`يعمل التأثير بعد أول رسم، فيومض المظهر الفاتح أولًا. أما سكربت صغير مضمّن في رأس المستند فيعمل قبل رسم أي شيء.`}},{id:`i-st-08`,phase:`styling`,question:{en:`Which style choice adds the most runtime cost?`,ar:`أي خيار تنسيق يضيف أكبر تكلفة وقت تشغيل؟`},options:[{text:{en:`Generating CSS in JavaScript while the app runs.`,ar:`توليد CSS في جافاسكربت أثناء تشغيل التطبيق.`},correct:!0},{text:{en:`Tailwind utility classes.`,ar:`أصناف أدوات Tailwind.`}},{text:{en:`CSS Modules.`,ar:`وحدات CSS.`}},{text:{en:`A plain stylesheet.`,ar:`ورقة أنماط عادية.`}}],explain:{en:`The first three are resolved at build time and ship as static CSS. Runtime CSS-in-JS has to compute and inject styles during render.`,ar:`تُحلّ الخيارات الثلاثة الأخرى وقت البناء وتُشحن كـ CSS ثابت. أما CSS-in-JS وقت التشغيل فعليه حساب الأنماط وحقنها أثناء العرض.`}},{id:`i-st-09`,phase:`styling`,question:{en:"Why prefer logical properties like `ps-4` over `pl-4` in a bilingual app?",ar:"لماذا تُفضَّل الخصائص المنطقية مثل `ps-4` على `pl-4` في تطبيق ثنائي اللغة؟"},options:[{text:{en:`They flip automatically with the writing direction.`,ar:`لأنها تنقلب تلقائيًا مع اتجاه الكتابة.`},correct:!0},{text:{en:`They produce smaller CSS.`,ar:`لأنها تُنتج CSS أصغر.`}},{text:{en:`They have higher specificity.`,ar:`لأن خصوصيتها أعلى.`}},{text:{en:`They are required for flexbox.`,ar:`لأنها مطلوبة لـ flexbox.`}}],explain:{en:'`padding-inline-start` means "the reading-start side", which is left in English and right in Arabic. Hard-coded left and right need a duplicate RTL stylesheet.',ar:"`padding-inline-start` تعني «جهة بداية القراءة»، وهي اليسار في الإنجليزية واليمين في العربية. أما اليسار واليمين الصريحان فيحتاجان ورقة أنماط مكرّرة للاتجاه من اليمين."}},{id:`i-st-10`,phase:`styling`,question:{en:"What is the risk of styling by element selector, like `div > p`?",ar:"ما خطر التنسيق بمُحدِّد العناصر مثل `div > p`؟"},options:[{text:{en:`It couples styles to markup structure, so refactoring breaks them.`,ar:`أنه يربط الأنماط ببنية الوسوم، فتنكسر عند إعادة الهيكلة.`},correct:!0},{text:{en:`Element selectors are slower than classes in modern browsers.`,ar:`أن مُحدِّدات العناصر أبطأ من الأصناف في المتصفحات الحديثة.`}},{text:{en:`They cannot be used with CSS Modules.`,ar:`أنها لا تُستخدم مع وحدات CSS.`}},{text:{en:`They do not support pseudo-classes.`,ar:`أنها لا تدعم الأصناف الزائفة.`}}],explain:{en:`Wrapping a paragraph in one extra element silently changes the design. Class-based styling states intent and survives structural change.`,ar:`تغليف فقرة بعنصر إضافي واحد يُغيّر التصميم بصمت. أما التنسيق بالأصناف فيُعلن النيّة ويصمد أمام تغيّر البنية.`}},{id:`i-st-11`,phase:`styling`,question:{en:`What is a container query useful for that a media query is not?`,ar:`فيمَ يفيد استعلام الحاوية ولا يفيد استعلام الوسائط؟`},options:[{text:{en:`Styling a component by the space it was given, not the viewport size.`,ar:`تنسيق مكوّن حسب المساحة الممنوحة له لا حسب حجم إطار العرض.`},correct:!0},{text:{en:`Detecting the user's device model.`,ar:`كشف طراز جهاز المستخدم.`}},{text:{en:`Applying dark mode.`,ar:`تطبيق الوضع الداكن.`}},{text:{en:`Loading different fonts.`,ar:`تحميل خطوط مختلفة.`}}],explain:{en:`A card in a narrow sidebar should stack even on a wide screen. Only the container knows how much room it actually has.`,ar:`البطاقة في شريط جانبي ضيّق يجب أن تتكدّس حتى على شاشة عريضة. والحاوية وحدها تعرف المساحة المتاحة لها فعلًا.`}},{id:`i-st-12`,phase:`styling`,question:{en:"Why is `focus-visible` preferred over removing focus outlines?",ar:"لماذا يُفضَّل `focus-visible` على إزالة حدود التركيز؟"},options:[{text:{en:`It keeps the ring for keyboard users while hiding it after a mouse click.`,ar:`لأنه يُبقي الحلقة لمستخدمي لوحة المفاتيح ويُخفيها بعد النقر بالفأرة.`},correct:!0},{text:{en:`It renders faster.`,ar:`لأنه يُعرض أسرع.`}},{text:{en:"It works in more browsers than `focus`.",ar:"لأنه يعمل في متصفحات أكثر من `focus`."}},{text:{en:`It removes the outline entirely.`,ar:`لأنه يزيل الحدّ تمامًا.`}}],explain:{en:"`outline: none` makes an interface unusable by keyboard — you cannot see where you are. `focus-visible` gives you the clean look without that cost.",ar:"`outline: none` تجعل الواجهة غير قابلة للاستخدام بلوحة المفاتيح — إذ لا ترى أين أنت. أما `focus-visible` فيمنحك المظهر النظيف دون تلك التكلفة."}},{id:`i-st-13`,phase:`styling`,question:{en:"How does a variant API such as `cva` help a component library?",ar:"كيف تساعد واجهة متغيّرات مثل `cva` مكتبة مكوّنات؟"},options:[{text:{en:"It maps props like `size` and `tone` to class sets in one declaration.",ar:"لأنها تربط خصائص مثل `size` و `tone` بمجموعات أصناف في تصريح واحد."},correct:!0},{text:{en:`It generates the CSS file.`,ar:`لأنها تُولّد ملف CSS.`}},{text:{en:`It replaces the need for props.`,ar:`لأنها تُلغي الحاجة إلى الخصائص.`}},{text:{en:`It compiles Tailwind.`,ar:`لأنها تُصرّف Tailwind.`}}],explain:{en:"The alternative is a growing chain of ternaries inside `className`. A variant table keeps the combinations declarative and typed.",ar:"البديل سلسلة متنامية من العوامل الثلاثية داخل `className`. أما جدول المتغيّرات فيُبقي التركيبات تصريحية ومُنمَّطة."}},{id:`i-st-14`,phase:`styling`,question:{en:`Why does Tailwind need to see your class names as complete strings?`,ar:`لماذا يحتاج Tailwind رؤية أسماء أصنافك كسلاسل كاملة؟`},options:[{text:{en:"It scans source files for literal names, so `` `p-${n}` `` is never generated.",ar:"لأنه يمسح الملفات بحثًا عن الأسماء الحرفية، فلا يُولَّد `` `p-${n}` `` أبدًا."},correct:!0},{text:{en:`It parses the runtime DOM.`,ar:`لأنه يحلّل DOM وقت التشغيل.`}},{text:{en:`It requires classes to be alphabetical.`,ar:`لأنه يتطلّب ترتيب الأصناف أبجديًا.`}},{text:{en:"It only reads `.css` files.",ar:"لأنه يقرأ ملفات `.css` فقط."}}],explain:{en:`The class only exists in the output if the exact string appears in your source. Map dynamic values to a lookup of full class names instead of building them.`,ar:`لا يوجد الصنف في الناتج إلا إذا ظهرت السلسلة الدقيقة في مصدرك. اربط القيم الديناميكية بجدول أسماء أصناف كاملة بدل تركيبها.`}},{id:`i-rd-01`,phase:`routing-and-data`,question:{en:`What distinguishes server state from client state?`,ar:`ما الذي يميّز حالة الخادم عن حالة العميل؟`},options:[{text:{en:`Server state is owned elsewhere and can go stale without you.`,ar:`أن حالة الخادم يملكها غيرك ويمكن أن تتقادم دون علمك.`},correct:!0},{text:{en:`Server state is always larger.`,ar:`أن حالة الخادم أكبر دائمًا.`}},{text:{en:`Client state cannot be persisted.`,ar:`أن حالة العميل لا يمكن حفظها.`}},{text:{en:`There is no real difference.`,ar:`أنه لا فرق حقيقي بينهما.`}}],explain:{en:`You hold a copy of someone else's data, so caching, refetching and invalidation all apply. Whether a sidebar is open has none of those problems.`,ar:`أنت تحتفظ بنسخة من بيانات غيرك، فينطبق عليها التخزين المؤقت وإعادة الجلب والإبطال. أما كون الشريط الجانبي مفتوحًا فلا يعاني شيئًا من ذلك.`}},{id:`i-rd-02`,phase:`routing-and-data`,question:{en:"Which problem does fetching inside `useEffect` NOT solve on its own?",ar:"أي مشكلة لا يحلّها الجلب داخل `useEffect` وحده؟"},options:[{text:{en:`Caching, so revisiting a page refetches from scratch.`,ar:`التخزين المؤقت، فتُعاد زيارة الصفحة بجلب من الصفر.`},correct:!0},{text:{en:`Running code after mount.`,ar:`تشغيل الكود بعد التركيب.`}},{text:{en:`Reading the response body.`,ar:`قراءة جسم الاستجابة.`}},{text:{en:`Setting a loading flag.`,ar:`ضبط عَلَم التحميل.`}}],explain:{en:`Race conditions, deduplication, retries, background refresh and cache invalidation are all still yours to write — which is what a query library exists for.`,ar:`تبقى تعارضات الطلبات وإزالة التكرار وإعادة المحاولة والتحديث الخلفي وإبطال الذاكرة المؤقتة من مسؤوليتك — وهذا سبب وجود مكتبات الاستعلام.`}},{id:`i-rd-03`,phase:`routing-and-data`,question:{en:`What is a query key used for?`,ar:`فيمَ يُستخدم مفتاح الاستعلام؟`},options:[{text:{en:`Identifying a cache entry so it can be shared, refetched and invalidated.`,ar:`تعريف مدخل في الذاكرة المؤقتة ليُشارَك ويُعاد جلبه ويُبطَل.`},correct:!0},{text:{en:`Authenticating the request.`,ar:`توثيق الطلب.`}},{text:{en:`Ordering results.`,ar:`ترتيب النتائج.`}},{text:{en:`Naming the component.`,ar:`تسمية المكوّن.`}}],explain:{en:'Include every input the request depends on — `["user", id]`, not just `["user"]` — or two different users will share one cache entry.',ar:'أدرج كل مُدخل يعتمد عليه الطلب — `["user", id]` لا `["user"]` فقط — وإلا تشارك مستخدمان مختلفان مدخلًا واحدًا في الذاكرة المؤقتة.'}},{id:`i-rd-04`,phase:`routing-and-data`,question:{en:`What does "stale time" control?`,ar:`ماذا تتحكّم فيه «مدة التقادم»؟`},options:[{text:{en:`How long cached data is trusted before a background refetch.`,ar:`كم تُصدَّق البيانات المخزّنة قبل إعادة جلب في الخلفية.`},correct:!0},{text:{en:`How long before the cache entry is deleted.`,ar:`كم يمرّ قبل حذف المدخل من الذاكرة المؤقتة.`}},{text:{en:`The request timeout.`,ar:`مهلة الطلب.`}},{text:{en:`How long a loading spinner shows.`,ar:`كم تظهر أيقونة التحميل.`}}],explain:{en:`Stale time is about freshness; garbage-collection time is about eviction. Fresh data is served without any network call at all.`,ar:`مدة التقادم تتعلّق بالحداثة، أما مدة جمع النفايات فتتعلّق بالإخلاء. والبيانات الحديثة تُقدَّم دون أي استدعاء شبكي إطلاقًا.`}},{id:`i-rd-05`,phase:`routing-and-data`,question:{en:`What is an optimistic update?`,ar:`ما التحديث التفاؤلي؟`},options:[{text:{en:`Showing the expected result immediately and rolling back if the server refuses.`,ar:`عرض النتيجة المتوقّعة فورًا والتراجع إن رفض الخادم.`},correct:!0},{text:{en:`Retrying a failed request automatically.`,ar:`إعادة محاولة طلب فاشل تلقائيًا.`}},{text:{en:`Prefetching data before it is needed.`,ar:`جلب البيانات مسبقًا قبل الحاجة إليها.`}},{text:{en:`Caching the response forever.`,ar:`تخزين الاستجابة إلى الأبد.`}}],explain:{en:`The rollback path is the part people forget. Without it a failed request leaves the screen showing something that never happened.`,ar:`مسار التراجع هو ما ينساه الناس. فبدونه يترك الطلب الفاشل الشاشة تعرض شيئًا لم يحدث قط.`}},{id:`i-rd-06`,phase:`routing-and-data`,question:{en:`After a successful mutation, why invalidate the related query?`,ar:`بعد تعديل ناجح، لماذا تُبطل الاستعلام المرتبط؟`},options:[{text:{en:`So the server stays the source of truth rather than your guess.`,ar:`ليبقى الخادم مصدر الحقيقة بدل تخمينك.`},correct:!0},{text:{en:`To clear the browser cache.`,ar:`لمسح ذاكرة المتصفح المؤقتة.`}},{text:{en:`To cancel pending requests.`,ar:`لإلغاء الطلبات المعلّقة.`}},{text:{en:`It is optional and rarely done.`,ar:`لأنه اختياري ونادرًا ما يُفعل.`}}],explain:{en:`The server may have added an id, a timestamp or a computed field your optimistic copy could not know about.`,ar:`قد يكون الخادم أضاف معرّفًا أو طابعًا زمنيًا أو حقلًا محسوبًا لا تعرفه نسختك التفاؤلية.`}},{id:`i-rd-07`,phase:`routing-and-data`,question:{en:`What does a nested route with a layout give you?`,ar:`ماذا يمنحك مسار متداخل مع تخطيط؟`},options:[{text:{en:`Shared chrome that stays mounted while the child route changes.`,ar:`هيكلًا مشتركًا يبقى مركّبًا بينما يتغيّر المسار الابن.`},correct:!0},{text:{en:`Automatic data fetching.`,ar:`جلب بيانات تلقائيًا.`}},{text:{en:`Server-side rendering.`,ar:`عرضًا من جهة الخادم.`}},{text:{en:`Smaller bundles.`,ar:`حزمًا أصغر.`}}],explain:{en:`The sidebar keeps its scroll position and state because it never unmounts — only the outlet below it swaps.`,ar:`يحتفظ الشريط الجانبي بموضع تمريره وحالته لأنه لا يُزال أبدًا — فلا يتبدّل إلا المنفذ الذي تحته.`}},{id:`i-rd-08`,phase:`routing-and-data`,question:{en:`Why keep a search filter in the URL rather than component state?`,ar:`لماذا تحفظ مُرشِّح البحث في الرابط بدل حالة المكوّن؟`},options:[{text:{en:`The view becomes shareable, bookmarkable and survives a refresh.`,ar:`لأن العرض يصبح قابلًا للمشاركة والحفظ ويصمد بعد التحديث.`},correct:!0},{text:{en:`URLs are faster to read than state.`,ar:`لأن قراءة الروابط أسرع من الحالة.`}},{text:{en:`It reduces re-renders.`,ar:`لأنه يقلّل إعادة العرض.`}},{text:{en:`Component state cannot hold strings.`,ar:`لأن حالة المكوّن لا تحمل نصوصًا.`}}],explain:{en:`The URL is state that the browser already manages for you — including the back button, which local state silently breaks.`,ar:`الرابط حالة يديرها المتصفح لك أصلًا — بما في ذلك زر الرجوع الذي تكسره الحالة المحلية بصمت.`}},{id:`i-rd-09`,phase:`routing-and-data`,question:{en:`Which states must a data-driven screen handle?`,ar:`أي حالات يجب أن تعالجها شاشة تعتمد على البيانات؟`},options:[{text:{en:`Loading, error, empty and success.`,ar:`التحميل والخطأ والفراغ والنجاح.`},correct:!0},{text:{en:`Loading and success only.`,ar:`التحميل والنجاح فقط.`}},{text:{en:`Success only; errors belong to the server.`,ar:`النجاح فقط، فالأخطاء من شأن الخادم.`}},{text:{en:`Error and success only.`,ar:`الخطأ والنجاح فقط.`}}],explain:{en:`Empty is the one that gets skipped, and it is where a first-time user lands. A blank screen reads as a bug.`,ar:`الفراغ هو ما يُتخطّى عادةً، وهو أول ما يصل إليه المستخدم الجديد. فالشاشة الفارغة تُقرأ كخلل.`}},{id:`i-rd-10`,phase:`routing-and-data`,question:{en:"What does `AbortController` do for a fetch inside an effect?",ar:"ماذا يفعل `AbortController` لطلب جلب داخل تأثير؟"},options:[{text:{en:`Cancels the in-flight request when the effect cleans up.`,ar:`يُلغي الطلب الجاري عند تنظيف التأثير.`},correct:!0},{text:{en:`Retries the request on failure.`,ar:`يُعيد محاولة الطلب عند الفشل.`}},{text:{en:`Caches the response.`,ar:`يخزّن الاستجابة مؤقتًا.`}},{text:{en:`Converts the response to JSON.`,ar:`يُحوّل الاستجابة إلى JSON.`}}],explain:{en:`Navigating away mid-request otherwise leaves a response arriving for a component that no longer exists — and a race with the next request.`,ar:`المغادرة أثناء الطلب تترك استجابةً تصل لمكوّن لم يعد موجودًا — وتعارضًا مع الطلب التالي.`}},{id:`i-rd-11`,phase:`routing-and-data`,question:{en:"What is `useInfiniteQuery` designed for?",ar:"لأي غرض صُمّمت `useInfiniteQuery`؟"},options:[{text:{en:`Accumulating pages of results behind one cache entry.`,ar:`تجميع صفحات النتائج خلف مدخل واحد في الذاكرة المؤقتة.`},correct:!0},{text:{en:`Polling a query forever.`,ar:`استطلاع استعلام إلى الأبد.`}},{text:{en:`Retrying indefinitely on error.`,ar:`إعادة المحاولة بلا حدّ عند الخطأ.`}},{text:{en:`Fetching every page at once.`,ar:`جلب كل الصفحات دفعة واحدة.`}}],explain:{en:`It keeps the pages together with a cursor, so going back to the list restores everything already loaded rather than starting from page one.`,ar:`تُبقي الصفحات معًا مع مؤشّر، فالعودة إلى القائمة تستعيد كل ما حُمّل بدل البدء من الصفحة الأولى.`}},{id:`i-rd-12`,phase:`routing-and-data`,question:{en:"How do you read `:userId` from the URL in React Router?",ar:"كيف تقرأ `:userId` من الرابط في React Router؟"},options:[{text:{en:"`const { userId } = useParams()`",ar:"`const { userId } = useParams()`"},correct:!0},{text:{en:"`const userId = useLocation()`",ar:"`const userId = useLocation()`"}},{text:{en:"`props.userId`",ar:"`props.userId`"}},{text:{en:"`window.params.userId`",ar:"`window.params.userId`"}}],explain:{en:"It is typed as possibly `undefined`, because nothing guarantees the component is rendered under that route — so guard before using it.",ar:"نوعه قد يكون `undefined` لأن لا شيء يضمن عرض المكوّن تحت ذلك المسار — فاحمِ الكود قبل استخدامه."}},{id:`i-rd-13`,phase:`routing-and-data`,question:{en:"Why does a classic paginated table blank out between pages without `placeholderData`?",ar:"لماذا يفرغ جدول مُرقَّم كلاسيكي بين الصفحات بدون `placeholderData`؟"},options:[{text:{en:`A new page is a new cache key, so the query starts empty and loading.`,ar:`لأن الصفحة الجديدة مفتاح جديد، فيبدأ الاستعلام فارغًا وفي حالة تحميل.`},correct:!0},{text:{en:`The old data is deleted from the server.`,ar:`لأن البيانات القديمة تُحذف من الخادم.`}},{text:{en:`The table component unmounts.`,ar:`لأن مكوّن الجدول يُزال.`}},{text:{en:`Pagination always clears state.`,ar:`لأن الترقيم يمسح الحالة دائمًا.`}}],explain:{en:`Keeping the previous page visible while the next loads avoids a jarring layout collapse — the row height stays put.`,ar:`إبقاء الصفحة السابقة مرئية أثناء تحميل التالية يتجنّب انهيار التخطيط المزعج — فيبقى ارتفاع الصفوف ثابتًا.`}},{id:`i-rd-14`,phase:`routing-and-data`,question:{en:'What is wrong with `<a href="/about">` for internal navigation in an SPA?',ar:'ما الخطأ في `<a href="/about">` للتنقّل الداخلي في تطبيق صفحة واحدة؟'},options:[{text:{en:`It triggers a full page reload, discarding all app state.`,ar:`لأنه يُحفّز إعادة تحميل كاملة فتضيع كل حالة التطبيق.`},correct:!0},{text:{en:`Anchors are not accessible.`,ar:`لأن الروابط غير متاحة للجميع.`}},{text:{en:`The URL will be wrong.`,ar:`لأن الرابط سيكون خاطئًا.`}},{text:{en:"Nothing — it is equivalent to `<Link>`.",ar:"لا شيء — فهو مكافئ لـ `<Link>`."}}],explain:{en:'`<Link>` renders a real anchor, so middle-click and "open in new tab" still work, but intercepts the click to navigate in the client.',ar:"يعرض `<Link>` رابطًا حقيقيًا فيبقى النقر الأوسط و«فتح في تبويب جديد» يعملان، لكنه يعترض النقرة للتنقّل داخل العميل."}},{id:`i-rd-15`,phase:`routing-and-data`,question:{en:`Two components request the same query key at the same time. What happens?`,ar:`مكوّنان يطلبان مفتاح الاستعلام نفسه في الوقت نفسه. ماذا يحدث؟`},options:[{text:{en:`One request is made and both receive the result.`,ar:`يُرسَل طلب واحد ويستقبل كلاهما النتيجة.`},correct:!0},{text:{en:`Two identical requests are sent.`,ar:`يُرسَل طلبان متطابقان.`}},{text:{en:`The second one errors.`,ar:`يفشل الثاني بخطأ.`}},{text:{en:`The second waits for a manual refetch.`,ar:`ينتظر الثاني إعادة جلب يدوية.`}}],explain:{en:`Deduplication by key is one of the biggest practical wins — the same data can be requested wherever it is needed without coordinating fetches.`,ar:`إزالة التكرار حسب المفتاح من أكبر المكاسب العملية — فيمكن طلب البيانات نفسها أينما احتيجت دون تنسيق بين الطلبات.`}},{id:`i-rd-16`,phase:`routing-and-data`,question:{en:"Why should a list item link to `/user/:id` rather than storing the selection in state?",ar:"لماذا يجب أن يربط عنصر القائمة بـ `/user/:id` بدل حفظ الاختيار في الحالة؟"},options:[{text:{en:`The selection becomes linkable and the back button works as expected.`,ar:`لأن الاختيار يصبح قابلًا للربط ويعمل زر الرجوع كما يُتوقّع.`},correct:!0},{text:{en:`Routing is faster than state.`,ar:`لأن التوجيه أسرع من الحالة.`}},{text:{en:`State cannot hold ids.`,ar:`لأن الحالة لا تحمل معرّفات.`}},{text:{en:`It avoids re-rendering the list.`,ar:`لأنه يتجنّب إعادة عرض القائمة.`}}],explain:{en:`If a user cannot send someone the thing they are looking at, that view is probably a route. Selection in state also means back closes the whole page.`,ar:`إن لم يستطع المستخدم إرسال ما ينظر إليه لشخص آخر، فذلك العرض على الأرجح مسار. كما أن الاختيار في الحالة يجعل زر الرجوع يُغلق الصفحة كلها.`}}];export{e as intermediateBank};